-- بيانات مقرر فيزياء 1 (المقرر 101، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L2-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين المخطط التوضيحي الآتي حركة سيارة على مرحلتين؛ في الأولى يرى السائق خطرًا أمامه ولم يضغط بعد على الفرامل، وفي الثانية يضغط على الفرامل حتى تقف. كيف تتحرك السيارة في المرحلة الأولى؟', null, '[{"src":"qimg/phys1/c3l2-o13-phases.svg","alt":"مخطط توضيحي للحركة (نموذج الجسيم النقطي) لسيارة تتحرك نحو اليمين، والاتجاه الموجب +x نحو اليمين. خط رأسي متقطع يقسم المخطط إلى «المرحلة الأولى» يسارًا و«المرحلة الثانية» يمينًا. في المرحلة الأولى أربع نقاط متساوية التباعد فوق كل منها سهم سرعة أحمر بالطول نفسه نحو اليمين. في المرحلة الثانية تتقارب النقاط تدريجيًا وتقصر أسهم السرعة الحمراء حتى تتلاصق النقاط الأخيرة، وفوق هذه المرحلة سهم تسارع بنفسجي a نحو اليسار."}]'::jsonb, '["بسرعة منتظمة مساوية لسرعتها الأولى","بتسارع ثابت سالب يقلل سرعتها تدريجيًا","بسرعة تتناقص إلى نصف قيمتها الابتدائية","تكون ساكنة حتى يضغط السائق على الفرامل"]'::jsonb, 'فهم', 'تفسير مخطط حركة', 'سهل', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('mcq', 2, 'يقود سائق سيارته بسرعة منتظمة 20 m/s، ورأى عائقًا أمامه فاستغرق 0.60 s قبل أن يضغط على الفرامل. ما مسافة الاستجابة؟', null, null, '["0.030 m","33 m","6.0 m","12 m"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('mcq', 3, 'تتحرك سيارة بسرعة متجهة $+20\ \text{m/s}$، فيرى سائقها خطرًا أمامه ويستغرق 0.50 s قبل أن يضغط على الفرامل، ثم تتباطأ السيارة بتسارع ثابت $-8.0\ \text{m/s}^2$ حتى تقف. ما الزمن الكلي من رؤية الخطر حتى توقف السيارة؟', null, null, '["2.5 s","3.0 s","2.0 s","1.8 s"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('mcq', 4, 'يقود سائق سيارة بسرعة 90.0 km/h، ورأى خطرًا فاستغرق 0.800 s ليضغط على الفرامل، ثم تباطأت السيارة بتسارع ثابت مقداره $5.00\ \text{m/s}^2$ حتى وقفت. ما المسافة الكلية التي قطعتها السيارة منذ رؤية الخطر حتى توقفها؟', null, null, '["882 m","62.5 m","82.5 m","145 m"]'::jsonb, 'تطبيق', 'حل مسألة متعددة المراحل', 'صعب', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('mcq', 5, 'إذا تضاعف زمن استجابة سائق (بسبب الإرهاق مثلًا) مع بقاء سرعة السيارة ومقدار تسارع الفرملة كما هما، فأيّ العبارات الآتية صحيحة؟', null, null, '["تصبح مسافة الاستجابة أربعة أمثال ما كانت عليه","تتضاعف مسافة الاستجابة ومسافة الفرملة كلتاهما","تتضاعف مسافة الفرملة، ولا تتغير مسافة الاستجابة","تتضاعف مسافة الاستجابة، ولا تتغير مسافة الفرملة"]'::jsonb, 'تحليل', 'تحليل أثر متغير', 'متوسط', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('mcq', 6, 'يقود سائق سيارة بسرعة 72.0 km/h، وفجأة رأى حاجزًا على بعد 45.0 m أمامه. استغرق 0.500 s حتى ضغط على الفرامل، ثم تباطأت السيارة بتسارع ثابت مقداره $6.00\ \text{m/s}^2$. ماذا يحدث؟', null, null, '["تقف السيارة قبل الحاجز بنحو 11.7 m","تقف السيارة قبل الحاجز بنحو 1.7 m","تصطدم بالحاجز؛ فمسافة توقفها 76.7 m","تصطدم بالحاجز؛ فمسافة توقفها 468 m"]'::jsonb, 'تحليل', 'حل مسألة واتخاذ قرار', 'صعب', 'الكتاب ص 90 — تقويم الفصل 90 (السائق والحاجز)'),
('mcq', 7, 'يبدأ متزلج حركته من السكون في خط مستقيم، فتزداد سرعته بانتظام إلى 6.0 m/s خلال 3.0 s، ثم يستمر بهذه السرعة المنتظمة مدة 5.0 s أخرى. ما المسافة الكلية التي يقطعها؟', null, null, '["39 m","48 m","30 m","9.0 m"]'::jsonb, 'تطبيق', 'حل مسألة متعددة المراحل', 'متوسط', 'الكتاب ص 78 — مراجعة 3-2 (35) ومسائل ص 77'),
('essay', 1, 'يقود سائق سيارته بسرعة منتظمة 28 m/s، وفجأة رأى طفلًا يركض في الشارع، فاستغرق 0.50 s ليضغط على الفرامل، ثم تباطأت السيارة بتسارع ثابت مقداره $7.0\ \text{m/s}^2$ حتى وقفت، كما يبين المخطط الآتي. اعتبر اتجاه سير السيارة موجبًا. (أ) احسب مسافة الاستجابة. (ب) احسب مسافة الفرملة. (ج) احسب المسافة الكلية والزمن الكلي من رؤية الطفل حتى التوقف.', null, '[{"src":"qimg/phys1/c3l2-o13-essay1.svg","alt":"مخطط توضيحي لحركة سيارة على طريق مستقيم نحو اليمين، والاتجاه الموجب +x نحو اليمين. ثلاثة خطوط رأسية متقطعة تحدد: «رؤية الطفل» عند اليسار، ثم «بدء الضغط على الفرامل» في المنتصف، ثم «التوقف» عند اليمين. الجزء الأول معنون «الاستجابة» وفيه نقاط متساوية التباعد فوقها أسهم سرعة حمراء متساوية الطول. الجزء الثاني معنون «الفرملة» وفيه نقاط تتقارب تدريجيًا وأسهم سرعة حمراء تقصر حتى التوقف، وتحته سهم تسارع بنفسجي a نحو اليسار."}]'::jsonb, null, 'تطبيق', 'حل مسألة متعددة المراحل', 'سهل', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)'),
('essay', 2, 'يتدرب عدّاء لسباق طوله 4.00 km؛ فيركض بسرعة منتظمة 4.50 m/s مدة 14.0 min، ثم يتسارع بمعدل ثابت حتى يجتاز خط النهاية بعد 40.0 s أخرى. (أ) احسب المسافة التي قطعها في المرحلة الأولى. (ب) احسب تسارعه في المرحلة الأخيرة. (ج) ما سرعته عند خط النهاية؟', null, null, null, 'تطبيق', 'حل مسألة متعددة المراحل', 'صعب', 'الكتاب ص 77 — مسائل تدريبية 29–32 (حركة متعددة المراحل)'),
('essay', 3, 'زمن استجابة سائق 0.80 s، ومقدار تسارع الفرملة لسيارته $6.0\ \text{m/s}^2$. (أ) احسب مسافة الاستجابة ومسافة الفرملة والمسافة الكلية للتوقف عندما تكون سرعة السيارة 15 m/s، ثم عندما تكون 30 m/s. (ب) قارن النتائج: كيف تغيرت كل مسافة عند مضاعفة السرعة؟ (ج) ماذا تستنتج عن خطورة السرعة العالية؟', null, null, null, 'تحليل', 'مقارنة وتحليل', 'متوسط', 'الكتاب ص 76 — مثال 5 (مسافتا الاستجابة والفرملة)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O13') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'في زمن الاستجابة لم تُستعمل الفرامل بعد، فتتحرك السيارة بسرعة منتظمة مساوية لسرعتها الأولى قبل رؤية الخطر؛ ولذلك تتساوى المسافات بين النقاط وأسهم السرعة في المرحلة الأولى، وتُحسب مسافة الاستجابة بالعلاقة $d = vt$.', '["","التسارع السالب يبدأ عند الضغط على الفرامل في المرحلة الثانية؛ والنقاط في المرحلة الأولى متساوية التباعد.","السرعة لا تتغير في زمن الاستجابة؛ فالمسافات بين النقاط في المرحلة الأولى متساوية.","السيارة تبقى متحركة في زمن الاستجابة، وتقطع خلاله مسافة الاستجابة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:58.897Z"}'::jsonb),
('mcq', 2, 3, 'في زمن الاستجابة تكون السرعة منتظمة: $d_{\text{r}} = vt = (20\ \text{m/s})(0.60\ \text{s}) = 12\ \text{m}$.', '["هذا ناتج قسمة الزمن على السرعة $\\frac{0.60}{20}$.","هذا ناتج قسمة السرعة على الزمن $\\frac{20}{0.60}$ بدل ضربهما.","ضُرب الناتج في $\\frac{1}{2}$ كأن السيارة تتسارع؛ لكن السرعة منتظمة في زمن الاستجابة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:58.897Z"}'::jsonb),
('mcq', 3, 1, 'في زمن الاستجابة (0.50 s) تتحرك السيارة بسرعة منتظمة. زمن الفرملة من $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$ مع $v_f = 0$: $t = \frac{0 - 20}{-8.0} = 2.5\ \text{s}$. الزمن الكلي $0.50 + 2.5 = 3.0\ \text{s}$.', '["هذا زمن الفرملة وحده؛ ونُسي زمن الاستجابة 0.50 s الذي تتحرك فيه السيارة بسرعة منتظمة قبل الضغط على الفرامل.","","طُرح زمن الاستجابة من زمن الفرملة $2.5 - 0.50$ بدل جمعه؛ والمرحلتان متتاليتان فيُجمع زمناهما.","حُسب زمن الفرملة بقسمة مسافة الفرملة 25 m على السرعة الابتدائية كأن السرعة منتظمة $\\frac{25}{20} \\approx 1.3\\ \\text{s}$ ثم أُضيف 0.50 s؛ لكن السرعة تتناقص في أثناء الفرملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:58.897Z"}'::jsonb),
('mcq', 4, 2, '$v = 90.0\ \text{km/h} = 25.0\ \text{m/s}$. الاستجابة: $d_{\text{r}} = (25.0)(0.800) = 20.0\ \text{m}$. الفرملة: $d_{\text{b}} = \frac{0 - 25.0^2}{2(-5.00)} = 62.5\ \text{m}$. الكلية: $20.0 + 62.5 = 82.5\ \text{m}$.', '["لم تُحوَّل السرعة من km/h إلى m/s: $(90.0)(0.800) + \\frac{90.0^2}{2(5.00)} = 72.0 + 810$.","هذه مسافة الفرملة وحدها؛ ونُسيت مسافة الاستجابة 20.0 m.","","نُسي العدد 2 في مقام مسافة الفرملة: $20.0 + \\frac{25.0^2}{5.00} = 20.0 + 125$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:58.897Z"}'::jsonb),
('mcq', 5, 3, 'مسافة الاستجابة $d_{\text{r}} = vt$ تتناسب طرديًا مع زمن الاستجابة فتتضاعف، أما مسافة الفرملة $\frac{v^2}{2\bar{a}}$ فتعتمد على السرعة والتسارع فقط فلا تتغير؛ وتزداد المسافة الكلية بمقدار مسافة الاستجابة الأصلية.', '["مسافة الاستجابة $vt$ تتناسب طرديًا مع الزمن لا مع مربعه.","مسافة الفرملة $\\frac{v^2}{2\\bar{a}}$ لا تعتمد على زمن الاستجابة.","زمن الاستجابة لا يدخل في حساب مسافة الفرملة، بل في مسافة الاستجابة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:58.897Z"}'::jsonb),
('mcq', 6, 1, '$v = 72.0\ \text{km/h} = 20.0\ \text{m/s}$. الاستجابة: $(20.0)(0.500) = 10.0\ \text{m}$. الفرملة: $\frac{20.0^2}{2(6.00)} = 33.3\ \text{m}$. مسافة التوقف $10.0 + 33.3 = 43.3\ \text{m}$، وهي أقل من 45.0 m؛ فتقف السيارة قبل الحاجز بنحو $45.0 - 43.3 = 1.7\ \text{m}$.', '["هذا ناتج إهمال مسافة الاستجابة 10.0 m وطرح مسافة الفرملة وحدها $45.0 - 33.3$.","","نُسي العدد 2 في مقام مسافة الفرملة: $10.0 + \\frac{20.0^2}{6.00}$.","لم تُحوَّل السرعة من km/h إلى m/s: $(72.0)(0.500) + \\frac{72.0^2}{2(6.00)}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:58.898Z"}'::jsonb),
('mcq', 7, 0, 'المرحلة الأولى: $\bar{a} = \frac{6.0}{3.0} = 2.0\ \text{m/s}^2$، و $\Delta d_1 = \frac{1}{2}(2.0)(3.0)^2 = 9.0\ \text{m}$. المرحلة الثانية: $\Delta d_2 = (6.0)(5.0) = 30\ \text{m}$. المجموع $9.0 + 30 = 39\ \text{m}$.', '["","عوملت الحركة كلها كأنها بسرعة منتظمة 6.0 m/s مدة 8.0 s، وأُهملت مرحلة التسارع من السكون.","هذه مسافة المرحلة الثانية (السرعة المنتظمة) فقط.","هذه مسافة المرحلة الأولى (التسارع) فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:58.898Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $d_{\text{r}} = vt = (28)(0.50) = 14\ \text{m}$. (ب) $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ مع $v_f = 0$ و $\bar{a} = -7.0\ \text{m/s}^2$: $d_{\text{b}} = \frac{0 - 28^2}{2(-7.0)} = 56\ \text{m}$. (ج) المسافة الكلية $14 + 56 = 70\ \text{m}$. زمن الفرملة $t = \frac{0 - 28}{-7.0} = 4.0\ \text{s}$، والزمن الكلي $0.50 + 4.0 = 4.5\ \text{s}$.', '["مسافة الاستجابة 14 m","مسافة الفرملة 56 m","المسافة الكلية 70 m","الزمن الكلي 4.5 s"]'::jsonb, '["$d_{\\text{r}} = (28\\ \\text{m/s})(0.50\\ \\text{s}) = 14\\ \\text{m}$","$d_{\\text{b}} = \\frac{0 - (28)^2}{2(-7.0)} = 56\\ \\text{m}$","$d = 14 + 56 = 70\\ \\text{m}$","$t_{\\text{b}} = \\frac{0 - 28}{-7.0} = 4.0\\ \\text{s}$ ، $t = 4.5\\ \\text{s}$"]'::jsonb, '[{"element":"مسافة الاستجابة","marks":1},{"element":"مسافة الفرملة","marks":1},{"element":"المسافة الكلية","marks":1},{"element":"الزمن الكلي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة بالوحدات والإشارات"},{"level":"2–3 درجات","description":"المسافتان صحيحتان مع خطأ في الكلية أو الزمن"},{"level":"1 درجة","description":"مسافة الاستجابة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال التسارع في مرحلة الاستجابة","إهمال إشارة التسارع فتظهر مسافة سالبة","نسيان إضافة زمن الاستجابة إلى زمن الفرملة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:58.898Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $t_1 = 14.0 \times 60 = 840\ \text{s}$، و $\Delta d_1 = (4.50)(840) = 3780\ \text{m}$. (ب) المسافة المتبقية $4000 - 3780 = 220\ \text{m}$، ومن $\Delta\boldsymbol{d} = \boldsymbol{v}_i t + \frac{1}{2}\boldsymbol{\bar{a}}t^2$: $220 = (4.50)(40.0) + \frac{1}{2}\bar{a}(40.0)^2$، أي $220 = 180 + 800\bar{a}$، فيكون $\bar{a} = 0.0500\ \text{m/s}^2$. (ج) $v_f = v_i + \bar{a}t = 4.50 + (0.0500)(40.0) = 6.50\ \text{m/s}$.', '["تحويل الزمن إلى ثوانٍ والمسافة 3780 m","المسافة المتبقية 220 m","التسارع $0.0500\\ \\text{m/s}^2$","السرعة النهائية 6.50 m/s"]'::jsonb, '["$\\Delta d_1 = (4.50)(840) = 3780\\ \\text{m}$","$\\Delta d_2 = 4000 - 3780 = 220\\ \\text{m}$","$220 = (4.50)(40.0) + \\frac{1}{2}\\bar{a}(40.0)^2 \\Rightarrow \\bar{a} = 0.0500\\ \\text{m/s}^2$","$v_f = 4.50 + (0.0500)(40.0) = 6.50\\ \\text{m/s}$"]'::jsonb, '[{"element":"مسافة المرحلة الأولى مع تحويل الزمن","marks":1},{"element":"المسافة المتبقية","marks":1},{"element":"حساب التسارع","marks":1},{"element":"السرعة النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"المرحلة الأولى صحيحة مع خطأ في حساب التسارع أو السرعة"},{"level":"1 درجة","description":"مسافة المرحلة الأولى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب السرعة في 14.0 دون تحويل الدقائق إلى ثوانٍ","افتراض أن المرحلة الأخيرة تبدأ من السكون","استعمال 4.00 km كاملة في المرحلة الأخيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:58.898Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عند 15 m/s: الاستجابة $(15)(0.80) = 12\ \text{m}$، والفرملة $\frac{15^2}{2(6.0)} = 18.75 \approx 19\ \text{m}$، والكلية $\approx 31\ \text{m}$. عند 30 m/s: الاستجابة $(30)(0.80) = 24\ \text{m}$، والفرملة $\frac{30^2}{2(6.0)} = 75\ \text{m}$، والكلية $99\ \text{m}$. (ب) تضاعفت مسافة الاستجابة (لأنها تتناسب مع $v$)، وصارت مسافة الفرملة أربعة أمثالها (لأنها تتناسب مع $v^2$)، فزادت المسافة الكلية إلى أكثر من ثلاثة أمثالها. (ج) مضاعفة السرعة تزيد مسافة التوقف زيادة كبيرة، معظمها من مسافة الفرملة؛ لذا يجب ترك مسافة أمان أكبر بكثير عند السرعات العالية.', '["الحسابات عند 15 m/s: 12 و 19 و 31 m","الحسابات عند 30 m/s: 24 و 75 و 99 m","الاستجابة تتضاعف والفرملة أربعة أمثال","استنتاج حول الأمان"]'::jsonb, '["$d_{\\text{r}} = vt$: 12 m و 24 m","$d_{\\text{b}} = \\frac{v^2}{2\\bar{a}}$: 18.75 m و 75 m","الكلية: 30.75 ≈ 31 m و 99 m"]'::jsonb, '[{"element":"الحسابات عند 15 m/s","marks":1},{"element":"الحسابات عند 30 m/s","marks":1},{"element":"المقارنة والتعليل","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة ومقارنة معللة واستنتاج سليم"},{"level":"2–3 درجات","description":"حسابات صحيحة مع مقارنة ناقصة"},{"level":"1 درجة","description":"حسابات إحدى الحالتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن مسافة الفرملة تتضاعف مرتين فقط","إهمال مسافة الاستجابة","استعمال زمن الاستجابة في حساب مسافة الفرملة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:58.898Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
