insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالسقوط الحر؟', null, null, '["حركة جسم نحو الأرض بسرعة متجهة ثابتة لا تتغير مع مرور الزمن","حركة جسم تحت تأثير الجاذبية الأرضية فقط بإهمال مقاومة الهواء","حركة جسم تحت تأثير الجاذبية الأرضية ومقاومة الهواء معًا","حركة جسم يبدأ من السكون ويتحرك إلى أسفل في أي وسط"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 79 — تعريف السقوط الحر'),
('mcq', 2, 'أيّ الحالات الآتية تمثل سقوطًا حرًا تقريبًا؟', null, null, '["ورقة صحيفة مفرودة تسقط في الغرفة","ريشة طائر تهبط ببطء في الهواء","حصاة صغيرة تسقط من ارتفاع مترين","مظلي يهبط بعد فتح مظلته"]'::jsonb, 'فهم', 'تطبيق تعريف على مواقف', 'سهل', 'الكتاب ص 79 — الورقة والحصاة؛ ص 87 السؤالان 61 و62'),
('mcq', 3, 'عند دراسة جسم يسقط سقوطًا حرًا، أيّ تأثير يُهمَل؟', null, null, '["تأثير مقاومة الهواء","تأثير الجاذبية الأرضية","التغير في السرعة المتجهة","تسارع الجسم نحو الأرض"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 79 — تعريف السقوط الحر'),
('mcq', 4, 'قُذفت كرة رأسيًا إلى أعلى، وكان تأثير مقاومة الهواء فيها مهملًا. متى تكون الكرة في حالة سقوط حر بعد مغادرتها اليد؟', null, null, '["في أثناء هبوطها فقط","عند أقصى ارتفاع تصل إليه فقط","في أثناء صعودها فقط","في أثناء صعودها وهبوطها معًا"]'::jsonb, 'فهم', 'تطبيق تعريف على مواقف', 'متوسط', 'الكتاب ص 79–80 — السقوط الحر وقذف كرة إلى أعلى'),
('mcq', 5, 'يُطلق على حركة جسم تحت تأثير الجاذبية الأرضية فقط، بإهمال تأثير مقاومة الهواء، مصطلح:', null, null, '["الحركة المنتظمة","السقوط الحر","التسارع المتوسط","الإزاحة الرأسية"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 79 — تعريف السقوط الحر'),
('mcq', 6, 'يبين الشكل الآتي مخططين توضيحيين (نموذج الجسيم النقطي) لجسمين A وB يسقطان نحو الأرض، والصور ملتقطة على فترات زمنية متساوية. أيّ الجسمين تمثل حركته سقوطًا حرًا طوال الوقت؟', null, '[{"src":"qimg/phys1/c3l3-o01-two-drops.svg","alt":"مخططان رأسيان بنموذج الجسيم النقطي لجسمين يسقطان نحو خط يمثل سطح الأرض، وتمثل كل نقطة موقع الجسم بعد فترات زمنية متساوية، والحركة من أعلى إلى أسفل. العمود الأيسر للجسم A: سبع نقاط تزداد المسافات بينها بانتظام من أعلى إلى أسفل (كل مسافة أكبر من التي قبلها بالمقدار نفسه) حتى تقترب آخر نقطة من الأرض. العمود الأيمن للجسم B: سبع نقاط؛ تزداد المسافات بين النقاط الأربع الأولى، ثم تصبح المسافات بين النقاط الأخيرة متساوية."}]'::jsonb, '["الجسم B؛ لأن المسافات بين صوره الأخيرة متساوية","الجسمان كلاهما؛ لأنهما يتحركان إلى أسفل نحو الأرض","الجسم A؛ لأن المسافات بين صوره المتتالية تزداد بانتظام حتى الأرض","الجسم B؛ لأن سرعته في نهاية الحركة أكبر من سرعة A"]'::jsonb, 'فهم', 'تفسير مخطط الحركة', 'متوسط', 'الكتاب ص 79–80 — السقوط الحر والمخطط التوضيحي للبيضة الساقطة'),
('mcq', 7, 'ريشة وحصاة أُسقطتا معًا داخل أنبوب زجاجي طويل فُرّغ من الهواء. أيّ العبارات الآتية تصف حركتيهما وصفًا صحيحًا؟', null, null, '["كلتاهما تسقط سقوطًا حرًا؛ لعدم وجود هواء يقاوم حركتهما","الحصاة وحدها تسقط سقوطًا حرًا؛ لأنها أثقل من الريشة","الريشة وحدها تسقط سقوطًا حرًا؛ لأنها أخف من الحصاة","لا تسقط أيّ منهما سقوطًا حرًا؛ لعدم وجود هواء داخل الأنبوب"]'::jsonb, 'فهم', 'تطبيق تعريف على مواقف', 'صعب', 'الكتاب ص 79 — تعريف السقوط الحر'),
('essay', 1, 'عرّف السقوط الحر، ثم وضّح الشرطين اللذين يتضمنهما التعريف، واذكر لماذا يمكن عدّ سقوط حجر من ارتفاع قليل سقوطًا حرًا تقريبًا.', null, null, null, 'فهم', 'تعريف وتعليل', 'متوسط', 'الكتاب ص 79 — تعريف السقوط الحر'),
('essay', 2, 'صنّف كل حالة مما يأتي إلى «سقوط حر تقريبًا» أو «ليس سقوطًا حرًا»، مع ذكر السبب: (أ) كرة فولاذية تسقط من ارتفاع 1.5 m. (ب) ورقة شجر جافة تسقط من غصنها. (ج) كرة تنس قُذفت رأسيًا إلى أعلى في أثناء صعودها (أهمل مقاومة الهواء). (د) مظلي يهبط بعد فتح مظلته.', null, null, null, 'تطبيق', 'تصنيف مواقف', 'صعب', 'الكتاب ص 79 وص 87 — السؤالان 61 و62'),
('essay', 3, 'يريد طالب أن يجعل ريشة تسقط سقوطًا حرًا. (أ) لماذا لا يكون سقوط الريشة في هواء الغرفة سقوطًا حرًا؟ (ب) اقترح طريقة تجعل سقوطها سقوطًا حرًا، وفسّر كيف تحقق طريقتك تعريف السقوط الحر.', null, null, null, 'تطبيق', 'اقتراح وتعليل', 'صعب', 'الكتاب ص 79 — تعريف السقوط الحر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
