from (values
('mcq', 1, 1, 'السقوط الحر هو حركة جسم تحت تأثير الجاذبية الأرضية فقط، مع إهمال تأثير مقاومة الهواء؛ لذلك تتزايد سرعته بانتظام.', '["الجسم الساقط سقوطًا حرًا يتسارع؛ فسرعته المتجهة تتغير بمقدار 9.80 m/s في كل ثانية ولا تبقى ثابتة.","","السقوط الحر يشترط إهمال مقاومة الهواء؛ فإذا أثرت مقاومة الهواء لم تعد الحركة سقوطًا حرًا.","لا يشترط أن يبدأ الجسم من السكون، والوسط مهم؛ فالشرط هو تأثير الجاذبية وحدها دون مقاومة الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:58.899Z"}'::jsonb),
('mcq', 2, 2, 'الحصاة ثقيلة نسبيًا ومساحة سطحها صغيرة، فيكون تأثير مقاومة الهواء في حركتها مهملًا، وتتحرك تحت تأثير الجاذبية الأرضية فقط تقريبًا؛ وهذا هو السقوط الحر.', '["الورقة المفرودة خفيفة ومنبسطة، فتؤثر مقاومة الهواء في سرعة هبوطها تأثيرًا كبيرًا لا يمكن إهماله.","الريشة خفيفة ومساحة سطحها كبيرة، فمقاومة الهواء تبطئ هبوطها كثيرًا ولا يمكن إهمالها.","","المظلة المفتوحة تجعل مقاومة الهواء كبيرة جدًا، فلا تكون الحركة تحت تأثير الجاذبية وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:58.899Z"}'::jsonb),
('mcq', 3, 0, 'تعريف السقوط الحر: حركة جسم تحت تأثير الجاذبية الأرضية فقط بإهمال تأثير مقاومة الهواء.', '["","الجاذبية الأرضية هي سبب السقوط الحر نفسه، فلا يمكن إهمالها.","السرعة المتجهة للجسم الساقط تتغير بانتظام، وهذا التغير جزء أساسي من وصف حركته.","الجسم الساقط سقوطًا حرًا يتسارع بالتسارع الناتج عن الجاذبية الأرضية؛ فالتسارع لا يُهمل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:58.899Z"}'::jsonb),
('mcq', 4, 3, 'بعد مغادرة اليد لا يؤثر في الكرة إلا الجاذبية الأرضية (مع إهمال مقاومة الهواء)، فهي في سقوط حر في أثناء صعودها وهبوطها معًا، وتسارعها g إلى أسفل في الحالتين.', '["السقوط الحر لا يعني أن الجسم يتحرك إلى أسفل؛ فالكرة الصاعدة أيضًا تتحرك تحت تأثير الجاذبية وحدها.","أقصى ارتفاع لحظة واحدة من الحركة، والكرة في سقوط حر قبلها وبعدها أيضًا.","الكرة الهابطة تتحرك تحت تأثير الجاذبية وحدها كذلك، فهي في سقوط حر في الهبوط أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:58.899Z"}'::jsonb),
('mcq', 5, 1, 'الحركة تحت تأثير الجاذبية الأرضية فقط، مع إهمال تأثير مقاومة الهواء، هي تعريف السقوط الحر؛ وفيها تتزايد السرعة المتجهة للجسم الساقط بانتظام.', '["الحركة المنتظمة حركة بسرعة متجهة ثابتة، أما الجسم الساقط فسرعته تتزايد.","","التسارع المتوسط كمية تصف معدل تغير السرعة المتجهة خلال فترة زمنية، وليس اسمًا لنوع من الحركة.","الإزاحة الرأسية تغير في موقع الجسم رأسيًا، وليست اسمًا لنوع الحركة الموصوفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb),
('mcq', 6, 2, 'في السقوط الحر تزداد السرعة باستمرار بمعدل ثابت (تسارع ثابت)، فتزداد المسافة بين الصور المتتالية بانتظام، وهذا ما يظهر في A. أما B فأصبحت المسافات بين صوره ثابتة، أي أن سرعته صارت ثابتة؛ وهذا يعني أن قوة أخرى (مقاومة الهواء) أثرت فيه، فلم يعد سقوطه حرًا.', '["تساوي المسافات يعني سرعة ثابتة وتسارعًا صفريًا، وهذا لا يحدث في السقوط الحر الذي تتزايد فيه السرعة باستمرار.","الحركة إلى أسفل وحدها لا تكفي؛ فالسقوط الحر يتطلب أن يتسارع الجسم باستمرار بتأثير الجاذبية وحدها.","","المسافات بين صور B الأخيرة أصغر من المسافات المقابلة في A، فسرعته في النهاية أقل، والسرعة الثابتة تعني أن سقوطه لم يعد حرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb),
('mcq', 7, 0, 'لعدم وجود هواء في الأنبوب لا يؤثر في الجسمين إلا الجاذبية الأرضية، فكلتاهما تسقط سقوطًا حرًا؛ إذ يتحرك كل منهما حركة سقوط حر تحقق التعريف تمامًا، بغض النظر عن وزنه أو شكله.', '["","وزن الجسم ليس شرطًا في تعريف السقوط الحر؛ فالشرط هو تأثير الجاذبية وحدها، وهذا متحقق للريشة أيضًا في الأنبوب المفرغ.","خفة الجسم ليست شرطًا للسقوط الحر، والحصاة أيضًا لا يؤثر فيها إلا الجاذبية داخل الأنبوب المفرغ.","السقوط الحر لا يحتاج إلى هواء؛ بل إن غياب الهواء يحقق شرطه، وهو إهمال مقاومة الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السقوط الحر هو حركة جسم تحت تأثير الجاذبية الأرضية فقط، بإهمال تأثير مقاومة الهواء. يتضمن التعريف شرطين: (1) أن تكون الجاذبية الأرضية هي المؤثر الوحيد في حركة الجسم، (2) أن يكون تأثير مقاومة الهواء مهملًا. الحجر ثقيل نسبيًا ومساحة سطحه صغيرة، فتأثير اصطدامه بجزيئات الهواء في سرعته ضعيف جدًا ويمكن إهماله عند السقوط من ارتفاع قليل؛ لذلك تكون حركته سقوطًا حرًا تقريبًا.', '["السقوط الحر: حركة جسم تحت تأثير الجاذبية الأرضية فقط","إهمال تأثير مقاومة الهواء","الحجر ثقيل وصغير المساحة فتأثير الهواء فيه مهمل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح","marks":1},{"element":"ذكر الشرطين","marks":1},{"element":"تعليل حالة الحجر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح كامل مع الشرطين وتعليل صحيح لحالة الحجر"},{"level":"2 درجة","description":"تعريف صحيح مع نقص في الشرطين أو في التعليل"},{"level":"1 درجة","description":"ذكر جزء من التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف السقوط الحر بأنه سقوط الجسم من السكون فقط","إغفال شرط إهمال مقاومة الهواء","تعليل سقوط الحجر حرًا بأنه «أثقل فيتسارع أكثر»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) سقوط حر تقريبًا: الكرة الفولاذية ثقيلة وصغيرة المساحة فتأثير الهواء فيها مهمل. (ب) ليس سقوطًا حرًا: الورقة خفيفة ومنبسطة فتؤثر مقاومة الهواء في سرعة هبوطها تأثيرًا كبيرًا. (ج) سقوط حر: بعد مغادرة اليد لا يؤثر فيها إلا الجاذبية الأرضية، والسقوط الحر يشمل الأجسام المقذوفة لا الساقطة من السكون فقط. (د) ليس سقوطًا حرًا: المظلة تجعل مقاومة الهواء كبيرة جدًا فلا يمكن إهمالها.', '["(أ) سقوط حر مع السبب","(ب) ليس سقوطًا حرًا مع السبب","(ج) سقوط حر رغم أن الكرة صاعدة","(د) ليس سقوطًا حرًا مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الحالة (ج)","marks":1},{"element":"الحالة (د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الحالات الأربع صحيحًا مع أسباب صحيحة"},{"level":"2–3 درجات","description":"تصنيف صحيح لحالتين أو ثلاث مع أسبابها"},{"level":"1 درجة","description":"تصنيف صحيح لحالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكرة الصاعدة ليست في سقوط حر لأنها تتحرك إلى أعلى","التصنيف دون ذكر دور مقاومة الهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الريشة خفيفة ومساحة سطحها كبيرة، فاصطدامها بجزيئات الهواء يؤثر في سرعة هبوطها تأثيرًا كبيرًا، فلا تكون الجاذبية الأرضية هي المؤثر الوحيد في حركتها. (ب) تُسقط الريشة داخل أنبوب طويل مفرغ من الهواء؛ فعندئذ لا توجد مقاومة هواء، وتتحرك الريشة تحت تأثير الجاذبية الأرضية فقط، وهذا هو تعريف السقوط الحر.', '["مقاومة الهواء تؤثر بشدة في الريشة الخفيفة المنبسطة","اقتراح التفريغ من الهواء (أنبوب مفرغ)","الربط بالتعريف: الجاذبية وحدها"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير عدم السقوط الحر في الهواء","marks":1},{"element":"اقتراح طريقة مناسبة","marks":1},{"element":"ربط الطريقة بالتعريف","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير صحيح واقتراح مناسب مربوط بالتعريف"},{"level":"2 درجة","description":"تفسير صحيح واقتراح دون ربط بالتعريف"},{"level":"1 درجة","description":"تفسير أو اقتراح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح زيادة ارتفاع الإسقاط بدل إزالة الهواء","القول إن الجاذبية لا تؤثر في الأجسام الخفيفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:58.900Z"}'::jsonb)
