('mcq', 4, 'ما معنى أن التسارع الناتج عن الجاذبية الأرضية يساوي 9.80 m/s² إلى أسفل؟', null, null, '["يقطع الجسم الساقط مسافة 9.80 m في كل ثانية من سقوطه","تزداد سرعته المتجهة إلى أسفل 9.80 m/s في كل ثانية","يسقط الجسم بسرعة ثابتة مقدارها 9.80 m/s طوال سقوطه","يزداد تسارع الجسم 9.80 m/s² في كل ثانية من سقوطه"]'::jsonb, 'فهم', 'تفسير معنى', 'متوسط', 'الكتاب ص 79 — مثال الصخرة الساقطة'),
('mcq', 5, 'يبين الجدول الآتي السرعة المتجهة لصخرة تسقط سقوطًا حرًا من السكون عند أزمنة مختلفة (الاتجاه الموجب إلى أسفل). ما القيمة الناقصة في الجدول؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","0.00"],["1.0","9.80"],["2.0","؟"],["3.0","29.4"]]}'::jsonb, null, '["39.2 m/s","14.7 m/s","19.6 m/s","9.80 m/s"]'::jsonb, 'تطبيق', 'استكمال جدول', 'متوسط', 'الكتاب ص 79 — بعد 1 s تكون 9.80 m/s وبعد 2 s تكون 19.60 m/s'),
('mcq', 6, 'يبين المنحنى الآتي السرعة المتجهة لحجر يسقط سقوطًا حرًا من السكون، والاتجاه الموجب إلى أسفل. ما قيمة ميل الخط، وماذا يمثل؟', null, '[{"src":"qimg/phys1/c3l3-o02-vt-stone.svg","alt":"منحنى (السرعة المتجهة – الزمن) لحجر يسقط سقوطًا حرًا. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 3.5 كل 0.5. المحور الرأسي: السرعة المتجهة (m/s) مدرّج بالقيم 0 و9.8 و19.6 و29.4 و39.2. خط مستقيم يبدأ من نقطة الأصل (0 s، 0 m/s) ويمر بالنقاط المعلّمة (1 s، 9.8 m/s) و(2 s، 19.6 m/s) وينتهي عند (3 s، 29.4 m/s)."}]'::jsonb, '["29.4 m/s²، ويمثل التسارع الناتج عن الجاذبية الأرضية","9.80 m/s، ويمثل السرعة المتجهة الثابتة للحجر","44.1 m، ويمثل إزاحة الحجر خلال 3.0 s","9.80 m/s²، ويمثل التسارع الناتج عن الجاذبية الأرضية"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 80 — ميل منحنى (السرعة المتجهة – الزمن) يساوي g'),
('mcq', 7, 'قاس طالبان قيمة g بدقة عالية في مدينتين مختلفتين، فحصل الأول على 9.78 m/s² والثاني على 9.82 m/s². ما التفسير الصحيح لهذا الاختلاف؟', null, null, '["قيمة g تتغير تغيرات طفيفة من موقع إلى آخر على سطح الأرض","أحد القياسين خاطئ حتمًا؛ لأن قيمة g ثابتة في كل مكان","استخدم الطالبان جسمين مختلفين في الكتلة فاختلف التسارع","أسقط الطالبان الجسمين من ارتفاعين مختلفين فاختلف التسارع"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'صعب', 'الكتاب ص 79 وص 84 — تغير قيمة g في مواقع مختلفة'),
('essay', 1, 'اكتب رمز التسارع الناتج عن الجاذبية الأرضية، وقيمته المتوسطة مع وحدتها، واتجاهه، ثم وضّح لماذا تُوصف هذه القيمة بأنها «متوسطة».', null, null, null, 'تذكر', 'تذكر حقائق', 'متوسط', 'الكتاب ص 79 — رمز تسارع الأجسام الساقطة g وقيمته المتوسطة'),
('essay', 2, 'أسقطت صخرة من السكون فسقطت سقوطًا حرًا (الاتجاه الموجب إلى أسفل). (أ) أكمل جدولًا يبين سرعتها المتجهة عند 0.0 s و1.0 s و2.0 s و3.0 s و4.0 s. (ب) ما مقدار الزيادة في السرعة المتجهة في كل ثانية؟ وما علاقة هذا المقدار بـ g؟', null, null, null, 'تطبيق', 'حساب وتفسير', 'سهل', 'الكتاب ص 79 — مثال الصخرة الساقطة'),
('essay', 3, 'ذكر طالب أن «قيمة g تساوي 9.80 m/s في كل مكان على الأرض». حدد الأخطاء في عبارته وصححها.', null, null, null, 'تقويم', 'تصحيح مفهوم', 'صعب', 'الكتاب ص 79 وص 86 — قيمة g ووحدتها')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
