('mcq', 2, 0, 'القيمة المتوسطة لـ g على سطح الأرض 9.80 m/s²، ووحدتها وحدة تسارع (m/s²).', '["","العدد صحيح لكن الوحدة m/s وحدة سرعة لا تسارع.","هذه سرعة جسم ساقط من السكون بعد 2 s بوحدة خاطئة، وليست قيمة g.","هذه قيمة تسارع الجاذبية على سطح القمر لا الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('mcq', 3, 3, 'تتغير قيمة g تغيرات طفيفة في أماكن مختلفة على الأرض (بحسب بعد الموقع عن مركز الأرض)، والقيمة المتوسطة لها 9.80 m/s².', '["قيمة g ليست ثابتة تمامًا؛ فهي تتغير تغيرات طفيفة من موقع إلى آخر، و9.80 m/s² قيمتها المتوسطة.","تسارع الأجسام الساقطة سقوطًا حرًا لا يتأثر بكتلتها أو وزنها.","g ثابتة في أثناء السقوط؛ فالذي يزداد مع الزمن هو السرعة المتجهة لا التسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('mcq', 4, 1, 'التسارع معدل تغير السرعة المتجهة؛ فـ 9.80 m/s² تعني أن السرعة المتجهة إلى أسفل تزداد 9.80 m/s كل ثانية: بعد 1 s تصبح 9.80 m/s، وبعد 2 s تصبح 19.6 m/s (إذا بدأ من السكون).', '["هذا خلط بين التسارع والسرعة؛ فالمسافة المقطوعة في كل ثانية ليست ثابتة بل تزداد.","","السرعة لا تبقى ثابتة في السقوط الحر؛ بل تتزايد بمقدار 9.80 m/s كل ثانية.","التسارع في السقوط الحر ثابت لا يزداد؛ فالذي يزداد 9.80 m/s في كل ثانية هو السرعة المتجهة لا التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('mcq', 5, 2, 'السرعة المتجهة لجسم يسقط سقوطًا حرًا من السكون تزداد بمقدار 9.80 m/s كل ثانية؛ فعند 2.0 s تكون $9.80 \times 2.0 = 19.6\ \text{m/s}$، وهذا يتفق مع 29.4 m/s عند 3.0 s.', '["هذا حاصل $g t^2 = 9.80 \\times 2.0^2$؛ ربع الزمن تربيعًا خطأ، فالسرعة تتناسب مع الزمن لا مع مربعه.","هذا متوسط السرعتين 0.00 و29.4 m/s (السرعة المتوسطة خلال 3.0 s)، وليس السرعة المتجهة عند 2.0 s.","","هذه السرعة عند 1.0 s؛ فقد افتُرض أن السرعة لا تتغير بعد الثانية الأولى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('mcq', 6, 3, 'الميل = $\frac{\Delta v}{\Delta t} = \frac{29.4 - 0}{3.0 - 0} = 9.80\ \text{m/s}^2$، وميل منحنى (السرعة المتجهة – الزمن) هو التسارع، وهنا هو التسارع الناتج عن الجاذبية الأرضية g.', '["29.4 m/s هي السرعة عند 3.0 s، وليست الميل؛ فالميل يتطلب القسمة على الفترة الزمنية 3.0 s.","الميل يمثل التسارع لا السرعة، والسرعة هنا ليست ثابتة بل تتزايد من 0 إلى 29.4 m/s.","44.1 m هي المساحة تحت المنحنى ($\\frac{1}{2} \\times 3.0 \\times 29.4$) وتمثل الإزاحة، لا الميل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('mcq', 7, 0, 'قيمة g تتغير تغيرات طفيفة في أماكن مختلفة على الأرض بحسب بعد الموقع عن مركز الأرض، وقيمتها المتوسطة 9.80 m/s²؛ فاختلاف بسيط كهذا متوقع.', '["","g ليست ثابتة تمامًا على سطح الأرض؛ فالاختلاف الطفيف بين المواقع حقيقي وليس بالضرورة خطأ قياس.","تسارع الجسم الساقط سقوطًا حرًا لا يتأثر بكتلته أو وزنه.","تسارع السقوط الحر لا يتأثر بالارتفاع الذي أُسقط منه الجسم في هذه التجارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الرمز $\boldsymbol{g}$، وقيمته المتوسطة 9.80 m/s²، واتجاهه دائمًا إلى أسفل (نحو الأرض). تُوصف بأنها متوسطة لأن قيمة g تتغير تغيرات طفيفة في أماكن مختلفة على سطح الأرض (بحسب بعد الموقع عن مركز الأرض)، فالعدد 9.80 m/s² يمثل متوسط هذه القيم.', '["الرمز g","القيمة 9.80 والوحدة m/s²","الاتجاه إلى أسفل","التغير الطفيف من مكان لآخر يفسر وصفها بالمتوسطة"]'::jsonb, '[]'::jsonb, '[{"element":"الرمز","marks":1},{"element":"القيمة والوحدة","marks":1},{"element":"الاتجاه","marks":1},{"element":"تعليل وصف «متوسطة»","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"الرمز والقيمة صحيحان مع نقص في الاتجاه أو التعليل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوحدة m/s بدل m/s²","القول إن g ثابتة تمامًا في كل مكان","القول إن اتجاه g في اتجاه حركة الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:58.901Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السرعة تزداد 9.80 m/s كل ثانية: عند 0.0 s: 0.00 m/s، عند 1.0 s: 9.80 m/s، عند 2.0 s: 19.6 m/s، عند 3.0 s: 29.4 m/s، عند 4.0 s: 39.2 m/s (كلها إلى أسفل). (ب) الزيادة في كل ثانية 9.80 m/s، وهي القيمة العددية لـ g؛ لأن g = 9.80 m/s² تعني تغيرًا في السرعة المتجهة مقداره 9.80 m/s في كل ثانية.', '["9.80 m/s عند 1.0 s","19.6 و29.4 و39.2 m/s","الزيادة 9.80 m/s كل ثانية","الربط بقيمة g = 9.80 m/s²"]'::jsonb, '["$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{g}t$ مع $v_i = 0$","$v(1.0) = 9.80 \\times 1.0 = 9.80\\ \\text{m/s}$","$v(2.0) = 19.6\\ \\text{m/s}$، $v(3.0) = 29.4\\ \\text{m/s}$، $v(4.0) = 39.2\\ \\text{m/s}$","$\\Delta v$ لكل ثانية $= 9.80\\ \\text{m/s}$"]'::jsonb, '[{"element":"القيم عند 1.0 و2.0 s","marks":1},{"element":"القيم عند 3.0 و4.0 s","marks":1},{"element":"مقدار الزيادة","marks":1},{"element":"العلاقة بـ g","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جدول صحيح كامل مع تفسير صحيح"},{"level":"2–3 درجات","description":"جدول صحيح دون ربط واضح بـ g، أو خطأ في قيمة واحدة"},{"level":"1 درجة","description":"قيمة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب السرعة بالعلاقة $g t^2$","جعل السرعة ثابتة 9.80 m/s","الخلط بين المسافة المقطوعة والسرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:58.902Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في العبارة خطآن: (1) الوحدة خاطئة؛ فـ g تسارع ووحدته m/s² لا m/s. (2) قيمة g ليست واحدة في كل مكان؛ فهي تتغير تغيرات طفيفة من موقع إلى آخر على الأرض، و9.80 m/s² هي قيمتها المتوسطة. العبارة الصحيحة: «القيمة المتوسطة لـ g على سطح الأرض 9.80 m/s²، واتجاهه إلى أسفل».', '["خطأ الوحدة: m/s² بدل m/s","خطأ ثبات القيمة: تتغير تغيرات طفيفة","صياغة العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ الوحدة وتصحيحه","marks":1},{"element":"تحديد خطأ ثبات القيمة وتصحيحه","marks":1},{"element":"صياغة صحيحة كاملة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد الخطأين وتصحيحهما بصياغة صحيحة"},{"level":"2 درجة","description":"تحديد الخطأين دون صياغة كاملة"},{"level":"1 درجة","description":"تحديد خطأ واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الوحدة فقط وإغفال تغير القيمة","القول إن g تتغير بتغير كتلة الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:58.902Z"}'::jsonb)
