select (select id from public.objectives where code = 'P1-C3-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي كرة تسقط سقوطًا حرًا، والاتجاه الموجب (+y) إلى أعلى كما هو مبين. ما قيمة التسارع التي تُعوَّض في معادلات الحركة لهذه الكرة؟', null, '[{"src":"qimg/phys1/c3l3-o03-axis-up.svg","alt":"كرة معلّقة في الهواء فوق خط يمثل سطح الأرض، ويخرج منها سهم أحمر رأسي إلى أسفل مكتوب بجانبه v يمثل سرعتها المتجهة. على يسار الشكل سهم أسود رأسي يشير إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب المختار."}]'::jsonb, '["$\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$","$\\boldsymbol{a} = -4.90\\ \\text{m/s}^2$","$\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$","$\\boldsymbol{a} = 0.00\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'تحديد إشارة', 'سهل', 'الكتاب ص 79–80 — إشارة التسارع الناتج عن الجاذبية الأرضية والنظام الإحداثي'),
('mcq', 2, 'يبين الشكل الآتي صورًا متتالية لبيضة تسقط سقوطًا حرًا التُقطت على فترات زمنية متساوية، والاتجاه الموجب (+y) إلى أسفل كما هو مبين. ما إشارتا السرعة المتجهة والتسارع للبيضة؟', null, '[{"src":"qimg/phys1/c3l3-o03-egg-strobe.svg","alt":"خمس صور متتالية لبيضة في عمود رأسي، التقطت على فترات زمنية متساوية في أثناء سقوطها إلى أسفل، والمسافة بين كل صورتين متتاليتين تزداد من أعلى إلى أسفل. على يسار الصور سهم أسود رأسي يشير إلى أسفل مكتوب عند رأسه +y يمثل الاتجاه الموجب المختار."}]'::jsonb, '["السرعة المتجهة موجبة والتسارع موجب","السرعة المتجهة موجبة والتسارع سالب","السرعة المتجهة سالبة والتسارع سالب","السرعة المتجهة سالبة والتسارع موجب"]'::jsonb, 'تطبيق', 'تحديد إشارة', 'سهل', 'الكتاب ص 80 — الشكل 3-14 البيضة الساقطة'),
('mcq', 3, 'قال طالب: «يوجد نوعان من تسارع الجاذبية الأرضية: تسارع موجب للأجسام الهابطة، وتسارع سالب للأجسام الصاعدة». ما التصحيح العلمي لعبارته؟', null, null, '["عبارته صحيحة؛ فإشارة g تتحدد باتجاه حركة الجسم، فتكون موجبة في الهبوط وسالبة في الصعود","يوجد تسارع جاذبية واحد مقداره 9.80 m/s² واتجاهه إلى أسفل، وإشارته في المعادلات يحددها الاتجاه الموجب المختار","تسارع الجاذبية سالب دائمًا في جميع المعادلات؛ لأن اتجاهه إلى أسفل مهما كان النظام الإحداثي","تسارع الجاذبية موجب دائمًا في جميع المعادلات؛ لأن مقداره 9.80 m/s² مهما كان النظام الإحداثي"]'::jsonb, 'فهم', 'تصحيح مفهوم', 'متوسط', 'الكتاب ص 79–80 وص 86 — تعتمد إشارة g في المعادلات على النظام الإحداثي'),
('mcq', 4, 'قُذفت كرة رأسيًا إلى أعلى، واختير الاتجاه الموجب إلى أعلى (أهمل مقاومة الهواء). ما إشارتا سرعتها المتجهة وتسارعها في أثناء صعودها؟', null, null, '["السرعة المتجهة موجبة، والتسارع موجب","السرعة المتجهة سالبة، والتسارع سالب","السرعة المتجهة سالبة، والتسارع موجب","السرعة المتجهة موجبة، والتسارع سالب"]'::jsonb, 'تطبيق', 'تحديد إشارة', 'متوسط', 'الكتاب ص 80 — قذف كرة إلى أعلى'),
('mcq', 5, 'حلّ طالبان المسألة نفسها: حجر يسقط سقوطًا حرًا من السكون مدة 1.5 s. اختار الأول الاتجاه الموجب إلى أعلى فحصل على $\boldsymbol{v}_f = -14.7\ \text{m/s}$. واختار الثاني الاتجاه الموجب إلى أسفل. ما السرعة المتجهة التي يحصل عليها الثاني؟', null, null, '["$+14.7\\ \\text{m/s}$","$-14.7\\ \\text{m/s}$","$+11.0\\ \\text{m/s}$","$+9.80\\ \\text{m/s}$"]'::jsonb, 'تحليل', 'مقارنة نظامين إحداثيين', 'متوسط', 'الكتاب ص 81 مثال عربة السقوط الحر، وص 82 المسألة 41c'),
('mcq', 6, 'يبين المنحنى الآتي السرعة المتجهة لكرة قُذفت رأسيًا إلى أعلى ثم عادت (أهمل مقاومة الهواء). أيّ اتجاه اختير موجبًا في هذا التمثيل؟', null, '[{"src":"qimg/phys1/c3l3-o03-vt-updown.svg","alt":"منحنى (السرعة المتجهة – الزمن) لكرة قذفت رأسيًا. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 3.5 كل 0.5. المحور الرأسي: السرعة المتجهة (m/s) مدرّج من −19.6 إلى 19.6 كل 4.9، ومحور الزمن عند السرعة صفر. خط مستقيم هابط يبدأ من (0 s، 14.7 m/s) ويقطع محور الزمن عند (1.5 s، 0 m/s) وينتهي عند (3.0 s، −14.7 m/s)."}]'::jsonb, '["إلى أسفل؛ لأن مقدار السرعة يتناقص في بداية الحركة","إلى أسفل؛ لأن السرعة المتجهة تصبح سالبة بعد 1.5 s","إلى أعلى؛ لأن الميل سالب والتسارع g إلى أسفل","لا يمكن تحديده؛ لأن الكرة تغيّر اتجاه حركتها"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 80 — الشكل 3-15a'),
('mcq', 7, 'سقط حجر من السكون سقوطًا حرًا، واختير الاتجاه الموجب إلى أسفل. أيّ معادلة تعطي سرعته المتجهة بعد زمن t بصورة صحيحة؟', null, null, '["$\\boldsymbol{v}_f = (-9.80\\ \\text{m/s}^2)\\,t$","$\\boldsymbol{v}_f = (+9.80\\ \\text{m/s}^2)\\,t$","$\\boldsymbol{v}_f = (+9.80\\ \\text{m/s}^2)\\,t^2$","$\\boldsymbol{v}_f = (+4.90\\ \\text{m/s}^2)\\,t$"]'::jsonb, 'تطبيق', 'اختيار معادلة', 'صعب', 'الكتاب ص 81 — معادلة السرعة المتجهة بدلالة التسارع الثابت'),
('essay', 1, 'أسقط عامل بناء قطعة قرميد من سطح بناية (أهمل مقاومة الهواء). (أ) باختيار الاتجاه الموجب إلى أعلى، احسب سرعتها المتجهة وإزاحتها بعد 4.0 s. (ب) أعد الحساب باختيار الاتجاه الموجب إلى أسفل. (ج) قارن بين الإجابتين، وهل تغيّرت الحركة الفعلية للقطعة؟', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 82 — المسألة 41'),
('essay', 2, 'فسّر لماذا لا يصح القول بوجود «تسارع جاذبية موجب» و«تسارع جاذبية سالب» نوعين مختلفين، ثم وضّح بمثال كرة قُذفت رأسيًا إلى أعلى ما الإشارة التي تُكتب للتسارع في أثناء صعودها وهبوطها إذا اخترت الاتجاه الموجب إلى أعلى، ثم إلى أسفل.', null, null, null, 'تحليل', 'تفسير وتصحيح مفهوم', 'صعب', 'الكتاب ص 79–80 وص 86'),
('essay', 3, 'قُذفت كرة رأسيًا إلى أعلى بسرعة 14.7 m/s (أهمل مقاومة الهواء). اختر الاتجاه الموجب إلى أسفل. (أ) اكتب قيمتي السرعة المتجهة الابتدائية والتسارع بإشارتيهما. (ب) احسب السرعة المتجهة للكرة بعد 2.0 s، وفسّر إشارة الناتج: هل الكرة صاعدة أم هابطة عندئذ؟', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 80 — قذف كرة إلى أعلى، وص 82 المسألة 41c')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التسارع الناتج عن الجاذبية الأرضية مقداره 9.80 m/s² واتجاهه إلى أسفل دائمًا. بما أن الاتجاه الموجب المختار إلى أعلى، فإن التسارع في عكس الاتجاه الموجب، فيُعوَّض $\boldsymbol{a} = -g = -9.80\ \text{m/s}^2$.', '["الإشارة الموجبة تعني أن التسارع إلى أعلى، أي في الاتجاه الموجب المختار، لكن g إلى أسفل؛ فهذه القيمة تصلح فقط إذا اختير الاتجاه الموجب إلى أسفل.","هذه القيمة $\\frac{1}{2}g$ التي تظهر في معادلة الموقع، وليست التسارع نفسه.","","التسارع لا يساوي صفرًا في السقوط الحر؛ فالسرعة المتجهة للكرة تتغير باستمرار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:58.902Z"}'::jsonb),
('mcq', 2, 0, 'البيضة تتحرك إلى أسفل، وهو الاتجاه الموجب المختار، فسرعتها المتجهة موجبة. والتسارع الناتج عن الجاذبية إلى أسفل أيضًا، فيكون موجبًا: $\boldsymbol{a} = +g = +9.80\ \text{m/s}^2$؛ ولذلك تزداد المسافات بين الصور المتتالية.', '["","التسارع إلى أسفل في الاتجاه الموجب المختار نفسه، فهو موجب لا سالب؛ ولو كان سالبًا لتناقصت السرعة.","هذه الإشارات تصح لو اختير الاتجاه الموجب إلى أعلى، أما هنا فالموجب إلى أسفل.","البيضة تتحرك إلى أسفل في الاتجاه الموجب، فسرعتها المتجهة موجبة لا سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:58.902Z"}'::jsonb),
('mcq', 3, 1, 'التسارع الناتج عن الجاذبية الأرضية واحد: مقداره 9.80 m/s² واتجاهه إلى أسفل دائمًا، سواء كان الجسم صاعدًا أم هابطًا. أما كتابته $-g$ أو $+g$ في المعادلات فتعتمد فقط على النظام الإحداثي: $-g$ إذا كان الموجب إلى أعلى، و$+g$ إذا كان الموجب إلى أسفل.', '["إشارة g لا تعتمد على اتجاه حركة الجسم؛ فتسارع الكرة الصاعدة والهابطة واحد (إلى أسفل)، والإشارة يحددها اختيار الاتجاه الموجب فقط.","","الإشارة ليست سالبة دائمًا؛ فإذا اختير الاتجاه الموجب إلى أسفل كُتب التسارع $+g$.","الإشارة ليست موجبة دائمًا؛ فإذا اختير الاتجاه الموجب إلى أعلى كُتب التسارع $-g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('mcq', 4, 3, 'في الصعود تتحرك الكرة إلى أعلى (الاتجاه الموجب) فسرعتها المتجهة موجبة، أما التسارع فإلى أسفل دائمًا فهو $\boldsymbol{a} = -g = -9.80\ \text{m/s}^2$. ولأنهما متعاكسان تتناقص سرعة الكرة في أثناء الصعود.', '["التسارع الناتج عن الجاذبية إلى أسفل حتى في أثناء الصعود، فهو سالب في هذا النظام؛ ولو كان موجبًا لتزايدت سرعة الكرة الصاعدة.","هذه إشارات الكرة في أثناء هبوطها، أما في الصعود فهي تتحرك في الاتجاه الموجب فسرعتها موجبة.","إشارتا السرعة والتسارع معكوستان هنا؛ فالكرة تصعد (سرعة موجبة) والتسارع إلى أسفل (سالب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('mcq', 5, 0, 'مع الموجب إلى أسفل: $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{g}t = 0 + (+9.80)(1.5) = +14.7\ \text{m/s}$. الإجابتان تصفان الحركة نفسها (14.7 m/s إلى أسفل)، والاختلاف في الإشارة فقط بسبب اختيار النظام الإحداثي.', '["","الإشارة السالبة تعني «إلى أسفل» في نظام الطالب الأول فقط؛ أما في نظام الثاني فالحركة إلى أسفل موجبة.","هذا مقدار الإزاحة $\\frac{1}{2}gt^2 \\approx 11\\ \\text{m}$ وليس السرعة المتجهة.","هذه قيمة g نفسها؛ فقد نُسي ضرب التسارع في الزمن 1.5 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('mcq', 6, 2, 'الميل $= \frac{-14.7 - 14.7}{3.0 - 0} = -9.80\ \text{m/s}^2$؛ أي أن التسارع سالب. وبما أن تسارع الجاذبية إلى أسفل دائمًا، فإن السالب هو «إلى أسفل»، والموجب إلى أعلى. ويتفق هذا مع أن السرعة الابتدائية موجبة والكرة قُذفت إلى أعلى.', '["تناقص مقدار السرعة في البداية يعني أن السرعة والتسارع متعاكسان، ولا يحدد وحده أي الاتجاهين موجب.","السرعة السالبة بعد 1.5 s تعني أن الكرة تهبط في الاتجاه السالب؛ فالسالب هو إلى أسفل والموجب إلى أعلى.","","يمكن تحديده من إشارة الميل (التسارع)؛ لأن اتجاه g معروف دائمًا إلى أسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('mcq', 7, 1, 'من $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{a}t$ مع $v_i = 0$ و$\boldsymbol{a} = +g$ (لأن g إلى أسفل والموجب إلى أسفل): $\boldsymbol{v}_f = (+9.80\ \text{m/s}^2)\,t$.', '["الإشارة السالبة تخص نظامًا موجبه إلى أعلى، أما هنا فالموجب إلى أسفل فيُكتب $+g$.","","السرعة المتجهة تتناسب مع الزمن لا مع مربعه؛ فـ $t^2$ تظهر في معادلة الموقع.","المعامل $\\frac{1}{2}$ يظهر في معادلة الموقع لا في معادلة السرعة المتجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\boldsymbol{a} = -9.80\ \text{m/s}^2$: $\boldsymbol{v}_f = 0 + (-9.80)(4.0) = -39.2 \approx -39\ \text{m/s}$، $\boldsymbol{d}_f = \frac{1}{2}(-9.80)(4.0)^2 = -78.4 \approx -78\ \text{m}$. (ب) $\boldsymbol{a} = +9.80\ \text{m/s}^2$: $\boldsymbol{v}_f = +39\ \text{m/s}$، $\boldsymbol{d}_f = +78\ \text{m}$. (ج) المقادير متساوية والإشارات متعاكسة فقط؛ فالحركة الفعلية واحدة: سرعة 39 m/s إلى أسفل وإزاحة 78 m إلى أسفل. الإشارة تعبّر عن الاتجاه بالنسبة إلى النظام الإحداثي المختار.', '["$\\boldsymbol{v}_f = -39\\ \\text{m/s}$ و$\\boldsymbol{d}_f = -78\\ \\text{m}$ (الموجب لأعلى)","$\\boldsymbol{v}_f = +39\\ \\text{m/s}$ و$\\boldsymbol{d}_f = +78\\ \\text{m}$ (الموجب لأسفل)","المقادير متساوية والإشارة فقط تختلف","الحركة الفعلية لم تتغير"]'::jsonb, '["$v_i = 0$، $t = 4.0\\ \\text{s}$","الموجب لأعلى: $\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$","$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{a}t = (-9.80)(4.0) = -39.2 \\approx -39\\ \\text{m/s}$","$\\boldsymbol{d}_f = \\boldsymbol{d}_i + \\boldsymbol{v}_i t + \\frac{1}{2}\\boldsymbol{a}t^2 = \\frac{1}{2}(-9.80)(4.0)^2 = -78.4 \\approx -78\\ \\text{m}$","الموجب لأسفل: $\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$ فتنعكس الإشارتان: $+39\\ \\text{m/s}$ و$+78\\ \\text{m}$"]'::jsonb, '[{"element":"حساب (أ)","marks":2},{"element":"حساب (ب)","marks":1},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة في النظامين مع استنتاج صحيح"},{"level":"2–3 درجات","description":"حسابات صحيحة في نظام واحد أو خطأ في الإشارة في الآخر"},{"level":"1 درجة","description":"حساب كمية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام $+g$ مع الموجب إلى أعلى","نسيان المعامل ½ في معادلة الإزاحة","استنتاج أن الحركة تختلف باختلاف النظام الإحداثي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:58.903Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التسارع الناتج عن الجاذبية الأرضية كمية واحدة: مقداره 9.80 m/s² واتجاهه إلى أسفل دائمًا، ولا يتغير بتغير اتجاه حركة الجسم. الإشارة في المعادلات مجرد طريقة لتمثيل هذا الاتجاه بالنسبة إلى المحور المختار. مثال الكرة: إذا كان الموجب إلى أعلى يُكتب $\boldsymbol{a} = -9.80\ \text{m/s}^2$ في الصعود وفي الهبوط معًا. وإذا كان الموجب إلى أسفل يُكتب $\boldsymbol{a} = +9.80\ \text{m/s}^2$ في الصعود وفي الهبوط معًا. أي أن الإشارة لا تتغير بين الصعود والهبوط، بل تتغير فقط عند تغيير النظام الإحداثي.', '["g واحد: 9.80 m/s² إلى أسفل دائمًا","الإشارة تعبير عن الاتجاه بالنسبة إلى المحور المختار","الموجب لأعلى: $-g$ في الصعود والهبوط","الموجب لأسفل: $+g$ في الصعود والهبوط"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير وحدة g","marks":1},{"element":"دور النظام الإحداثي","marks":1},{"element":"الحالة الأولى صحيحة","marks":1},{"element":"الحالة الثانية صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح مع إشارات صحيحة في الحالتين للصعود والهبوط"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في إحدى الحالات"},{"level":"1 درجة","description":"ذكر أن g إلى أسفل دون تفسير الإشارة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير إشارة g بين الصعود والهبوط","ربط إشارة g باتجاه السرعة المتجهة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:58.904Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الكرة تتحرك ابتداءً إلى أعلى (عكس الموجب): $\boldsymbol{v}_i = -14.7\ \text{m/s}$، والتسارع إلى أسفل (الموجب): $\boldsymbol{a} = +9.80\ \text{m/s}^2$. (ب) $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{a}t = -14.7 + (9.80)(2.0) = +4.9\ \text{m/s}$. الإشارة الموجبة تعني أن الكرة تتحرك إلى أسفل؛ أي أنها وصلت إلى أقصى ارتفاع (عند 1.5 s) ثم بدأت تهبط بسرعة 4.9 m/s.', '["$\\boldsymbol{v}_i = -14.7\\ \\text{m/s}$","$\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$","$\\boldsymbol{v}_f = +4.9\\ \\text{m/s}$","الإشارة الموجبة تعني أن الكرة هابطة"]'::jsonb, '["$\\boldsymbol{v}_i = -14.7\\ \\text{m/s}$، $\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$، $t = 2.0\\ \\text{s}$","$\\boldsymbol{v}_f = -14.7 + (9.80)(2.0)$","$\\boldsymbol{v}_f = -14.7 + 19.6 = +4.9\\ \\text{m/s}$"]'::jsonb, '[{"element":"إشارة السرعة الابتدائية","marks":1},{"element":"إشارة التسارع","marks":1},{"element":"حساب السرعة النهائية","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إشارات صحيحة وحساب صحيح وتفسير صحيح"},{"level":"2–3 درجات","description":"حساب صحيح مع خطأ في إحدى الإشارات أو في التفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل السرعة الابتدائية موجبة لأنها «سرعة القذف»","كتابة $-g$ لأن الجاذبية «تعاكس» الصعود","تفسير الناتج الموجب بأن الكرة ما زالت صاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:58.904Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
