select (select id from public.objectives where code = 'P1-C3-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالتسارع الناتج عن الجاذبية الأرضية؟', null, null, '["سرعة الجسم الساقط لحظة اصطدامه بسطح الأرض","المسافة التي يقطعها الجسم الساقط في الثانية الأولى","تسارع جسم يتحرك أفقيًا على سطح الأرض بسرعة ثابتة","تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 79 — تعريف التسارع الناتج عن الجاذبية الأرضية'),
('mcq', 2, '«تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه». ما المصطلح الذي تعرّفه هذه العبارة؟', null, null, '["التسارع الناتج عن الجاذبية الأرضية","التسارع اللحظي للجسم الساقط","التسارع المتوسط للجسم الساقط","السرعة المتجهة النهائية للجسم"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 79 — تعريف التسارع الناتج عن الجاذبية الأرضية'),
('mcq', 3, 'ما اتجاه التسارع الناتج عن الجاذبية الأرضية لجسم يتحرك حركة سقوط حر؟', null, null, '["في اتجاه حركة الجسم دائمًا","إلى أعلى عند الصعود وإلى أسفل عند الهبوط","إلى أسفل نحو الأرض دائمًا","إلى أعلى دائمًا عكس اتجاه السقوط"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 79–81 وص 86 — g إلى أسفل'),
('mcq', 4, 'أُسقطت الكرة A من السكون، وقُذفت الكرة B رأسيًا إلى أسفل بسرعة 5.0 m/s من الموقع نفسه (أهمل مقاومة الهواء). كيف يُقارن تسارعاهما في أثناء السقوط؟', null, null, '["تسارع B أكبر؛ لأن سرعتها الابتدائية أكبر","متساويان، وكل منهما 9.80 m/s² إلى أسفل","تسارع A أكبر؛ لأنها بدأت من السكون","تسارع B يساوي 5.0 m/s² وتسارع A يساوي 9.80 m/s²"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 79 — التسارع لا يتأثر بكون الجسم قد أُسقط أو قُذف'),
('mcq', 5, 'يبين الشكل الآتي مخططًا توضيحيًا لجسم يسقط سقوطًا حرًا، تمثل فيه النقاط مواقعه على فترات زمنية متساوية، والأسهم الحمراء سرعته المتجهة. ماذا تستنتج عن تسارعه؟', null, '[{"src":"qimg/phys1/c3l3-o04-motion.svg","alt":"مخطط توضيحي رأسي لجسم يسقط: سبع نقاط في عمود رأسي من أعلى إلى أسفل تزداد المسافات بينها بانتظام. بجانب النقاط الست الأولى أسهم حمراء رأسية تشير إلى أسفل مكتوب بجانبها v، وتزداد أطوالها بالمقدار نفسه من سهم إلى الذي يليه (الأطوال بنسبة 1 : 2 : 3 : 4 : 5 : 6)."}]'::jsonb, '["يزداد مع الزمن؛ لأن المسافات بين النقاط المتتالية تزداد باستمرار","يساوي صفرًا؛ لأن الأسهم جميعها في الاتجاه نفسه","ثابت واتجاهه إلى أسفل؛ لأن السرعة تزداد بالمقدار نفسه في كل فترة","اتجاهه إلى أعلى؛ لأنه يعاكس حركة الجسم الساقط"]'::jsonb, 'فهم', 'تفسير مخطط الحركة', 'متوسط', 'الكتاب ص 80 — المخطط التوضيحي لحركة البيضة الساقطة'),
('mcq', 6, 'حجر يسقط سقوطًا حرًا من أعلى برج مرتفع. كيف يتغير مقدار تسارعه في أثناء سقوطه؟', null, null, '["يبقى ثابتًا ومقداره 9.80 m/s²","يزداد باستمرار لأن سرعته تزداد","يتناقص كلما اقترب الحجر من الأرض","يبدأ من الصفر ثم يزداد تدريجيًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 79–80 — تسارع ثابت مقداره 9.80 m/s²'),
('mcq', 7, 'يبين الشكل الآتي أربعة منحنيات (التسارع – الزمن). إذا اختير الاتجاه الموجب إلى أسفل، فأيّ منحنى يمثل حركة حجر يسقط سقوطًا حرًا؟', null, '[{"src":"qimg/phys1/c3l3-o04-at-panels.svg","alt":"أربعة منحنيات صغيرة (التسارع – الزمن) مسمّاة A وB وC وD، المحور الأفقي في كل منها الزمن t بالثانية (s)، والمحور الرأسي التسارع a بوحدة m/s² مدرّج بالقيم −9.8 و0 و9.8. المنحنى A: خط أفقي عند +9.8. المنحنى B: خط مائل يبدأ من 0 عند t = 0 ويزداد حتى 9.8 عند t = 3 s. المنحنى C: خط أفقي منطبق على محور الزمن عند 0. المنحنى D: خط أفقي عند −9.8."}]'::jsonb, '["المنحنى A","المنحنى B","المنحنى C","المنحنى D"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 80 — تسارع الكرة ثابت عند أي نقطة'),
('essay', 1, 'عرّف التسارع الناتج عن الجاذبية الأرضية، ثم استخدم التعريف للإجابة عمّا يأتي (أهمل مقاومة الهواء إلا حيث يُذكر الهواء): (أ) هل تسارع كرة قُذفت رأسيًا إلى أعلى، في أثناء صعودها بعد مغادرتها اليد، هو التسارع الناتج عن الجاذبية الأرضية؟ علّل. (ب) ما اتجاه هذا التسارع في أثناء صعودها؟ (ج) لماذا لا يُعدّ تسارع ريشة تهبط في هواء الغرفة هو التسارع الناتج عن الجاذبية الأرضية؟', null, null, null, 'فهم', 'تعريف وتطبيق', 'متوسط', 'الكتاب ص 79–81 — تعريف التسارع الناتج عن الجاذبية الأرضية'),
('essay', 2, 'قارن بين تسارع ثلاثة أحجار متماثلة (مقدارًا واتجاهًا) بعد إفلاتها، مع إهمال مقاومة الهواء: (أ) حجر أُسقط من السكون، (ب) حجر قُذف رأسيًا إلى أسفل، (ج) حجر قُذف رأسيًا إلى أعلى وما زال صاعدًا. ثم فسّر نتيجة المقارنة.', null, null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 79 — التسارع لا يتأثر بكون الجسم قد أُسقط أو قُذف'),
('essay', 3, 'يبين الجدول الآتي السرعة المتجهة لحجر يسقط سقوطًا حرًا (الاتجاه الموجب إلى أسفل). (أ) احسب التسارع المتوسط في كل فترة زمنية متتالية. (ب) ماذا تستنتج عن تسارع الحجر؟ وما اسم هذا التسارع؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.00","0.00"],["0.50","4.90"],["1.00","9.80"],["1.50","14.7"]]}'::jsonb, null, null, 'تطبيق', 'تحليل بيانات', 'صعب', 'الكتاب ص 79 — تزداد السرعة المتجهة إلى أسفل بمعدل 9.80 m/s كل ثانية')
