from (values
('mcq', 1, 3, 'التسارع الناتج عن الجاذبية الأرضية هو تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه، ومقداره المتوسط 9.80 m/s² إلى أسفل.', '["هذه سرعة لا تسارع؛ والتسارع معدل تغير السرعة لا قيمتها عند لحظة الاصطدام.","هذه مسافة لا تسارع.","الجسم الذي يتحرك بسرعة ثابتة تسارعه صفر، ولا علاقة لهذا بالسقوط الحر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 2, 0, 'هذا تعريف التسارع الناتج عن الجاذبية الأرضية، ويُرمز له بالرمز g.', '["","التسارع اللحظي هو التغير في السرعة عند لحظة زمنية محددة لأي جسم، وليس خاصًا بالسقوط الحر.","التسارع المتوسط هو التغير في السرعة المتجهة مقسومًا على الفترة الزمنية لأي حركة، وليس خاصًا بالسقوط الحر.","السرعة المتجهة النهائية سرعة لا تسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 3, 2, 'التسارع الناتج عن الجاذبية الأرضية إلى أسفل دائمًا (نحو الأرض)، سواء كان الجسم صاعدًا أم هابطًا أم عند أقصى ارتفاع.', '["الجسم المقذوف إلى أعلى يتحرك إلى أعلى بينما تسارعه إلى أسفل؛ فالتسارع ليس دائمًا في اتجاه الحركة.","التسارع لا يتغير اتجاهه بين الصعود والهبوط؛ فهو إلى أسفل في الحالتين.","","الجاذبية تجذب الأجسام نحو الأرض، فتسارعها إلى أسفل لا إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 4, 1, 'التسارع الناتج عن الجاذبية الأرضية لا يتأثر بكون الجسم قد أُسقط أو قُذف؛ فكلتا الكرتين تسقط سقوطًا حرًا بتسارع g = 9.80 m/s² إلى أسفل. السرعة الابتدائية تؤثر في السرعة عند كل لحظة لا في التسارع.', '["السرعة الابتدائية لا تحدد التسارع؛ فالتسارع هو معدل تغير السرعة، وهو g للكرتين.","","البدء من السكون لا يزيد التسارع؛ فكلتاهما تتسارع بالمقدار نفسه g.","الخلط بين السرعة الابتدائية (5.0 m/s) والتسارع؛ فتسارع B هو g أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 5, 2, 'أطوال أسهم السرعة تزداد بمقادير متساوية في الفترات الزمنية المتساوية، أي أن التغير في السرعة ثابت، فالتسارع ثابت (هو g) واتجاهه في اتجاه زيادة السرعة، أي إلى أسفل.', '["ازدياد المسافات يعني ازدياد السرعة لا ازدياد التسارع؛ فالسرعة تزداد بمقادير متساوية، فالتسارع ثابت.","تساوي اتجاه الأسهم لا يعني تسارعًا صفريًا؛ فأطوالها تتغير، أي أن السرعة تتغير.","","لو كان التسارع إلى أعلى لتناقصت السرعة، لكن الأسهم تطول باستمرار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 6, 0, 'تسارع الجسم الساقط سقوطًا حرًا ثابت طوال السقوط ويساوي g = 9.80 m/s²؛ أما السرعة فهي التي تزداد بمعدل ثابت.', '["","ازدياد السرعة لا يعني ازدياد التسارع؛ فالسرعة تزداد بمعدل ثابت هو g.","التسارع لا يتناقص في السقوط الحر؛ فهو ثابت حتى لحظة الاصطدام.","الحجر يتسارع بـ g منذ لحظة إفلاته؛ والذي يبدأ من الصفر هو السرعة لا التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('mcq', 7, 0, 'التسارع الناتج عن الجاذبية ثابت مقداره 9.80 m/s² واتجاهه إلى أسفل؛ ومع الموجب إلى أسفل يكون $\boldsymbol{a} = +9.80\ \text{m/s}^2$ ثابتًا مع الزمن، فيمثله خط أفقي عند $+9.8$، وهو المنحنى A.', '["","المنحنى B يمثل تسارعًا يزداد مع الزمن، وهذا وصف السرعة المتجهة للحجر لا تسارعه.","المنحنى C يمثل تسارعًا صفريًا، أي سرعة ثابتة، وهذا لا يحدث في السقوط الحر.","المنحنى D يمثل $-9.80\\ \\text{m/s}^2$، وهذا يصح لو كان الموجب إلى أعلى، لا في النظام المحدد هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:58.905Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع الناتج عن الجاذبية الأرضية هو تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه. (أ) نعم؛ فبعد مغادرة اليد لا يؤثر في الكرة إلا الجاذبية الأرضية، فهي في سقوط حر حتى وهي صاعدة، وتسارعها هو $\boldsymbol{g}$. (ب) إلى أسفل نحو الأرض، أي عكس اتجاه حركتها؛ ولهذا تتناقص سرعتها في أثناء الصعود. (ج) لأن الريشة لا تسقط سقوطًا حرًا؛ فمقاومة الهواء تؤثر في هبوطها تأثيرًا كبيرًا إلى جانب الجاذبية، فلا يكون تسارعها هو التسارع الذي يعرّفه المصطلح (تسارع جسم يسقط سقوطًا حرًا).', '["التعريف: تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه","الكرة الصاعدة في سقوط حر فتسارعها g","الاتجاه إلى أسفل حتى في أثناء الصعود","الريشة في الهواء ليست في سقوط حر لتأثير مقاومة الهواء"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"(أ) مع التعليل","marks":1},{"element":"(ب) الاتجاه","marks":1},{"element":"(ج) مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وإجابات معللة صحيحة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"تعريف صحيح مع خطأ أو نقص في جزء أو جزأين"},{"level":"1 درجة","description":"التعريف فقط أو جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تسارع الكرة الصاعدة إلى أعلى","القول إن الكرة لا تكون في سقوط حر إلا في أثناء هبوطها","تعريف التسارع الناتج عن الجاذبية بأنه سرعة الجسم الساقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:58.906Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التسارع في الحالات الثلاث متساوٍ: مقداره 9.80 m/s² واتجاهه إلى أسفل. التفسير: بعد الإفلات لا يؤثر في أي حجر إلا الجاذبية الأرضية، فكل منها يسقط سقوطًا حرًا، والتسارع الناتج عن الجاذبية الأرضية لا يتأثر بكون الجسم قد أُسقط أو قُذف ولا باتجاه حركته. الذي يختلف بينها هو السرعة المتجهة: تزداد في (أ) و(ب)، وتتناقص في (ج) لأن السرعة إلى أعلى والتسارع إلى أسفل.', '["التسارع 9.80 m/s² في الحالات الثلاث","الاتجاه إلى أسفل في الحالات الثلاث","التفسير: الجاذبية وحدها تؤثر بعد الإفلات","الاختلاف في السرعة المتجهة لا في التسارع"]'::jsonb, '[]'::jsonb, '[{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1},{"element":"التفسير","marks":1},{"element":"التمييز بين السرعة والتسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة وتفسير كامل"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تفسير ناقص"},{"level":"1 درجة","description":"المقدار صحيح دون الاتجاه أو التفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل تسارع الحجر الصاعد إلى أعلى","القول إن الحجر المقذوف إلى أسفل تسارعه أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:58.906Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في كل فترة مدتها 0.50 s تزداد السرعة 4.90 m/s: $\bar{\boldsymbol{a}} = \frac{4.90}{0.50} = 9.80\ \text{m/s}^2$ في الفترات الثلاث (0.0–0.5 s، 0.5–1.0 s، 1.0–1.5 s). (ب) التسارع ثابت مقداره 9.80 m/s² واتجاهه إلى أسفل (موجب في هذا النظام)، وهو التسارع الناتج عن الجاذبية الأرضية g.', '["حساب التسارع في الفترات الثلاث","كل فترة تعطي 9.80 m/s²","التسارع ثابت إلى أسفل","تسميته التسارع الناتج عن الجاذبية الأرضية"]'::jsonb, '["$\\bar{\\boldsymbol{a}} = \\frac{\\Delta \\boldsymbol{v}}{\\Delta t}$","$\\frac{4.90 - 0.00}{0.50} = 9.80\\ \\text{m/s}^2$","$\\frac{9.80 - 4.90}{0.50} = 9.80\\ \\text{m/s}^2$","$\\frac{14.7 - 9.80}{0.50} = 9.80\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"القانون","marks":1},{"element":"الحسابات الثلاثة","marks":1},{"element":"استنتاج الثبات والاتجاه","marks":1},{"element":"التسمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة واستنتاج وتسمية صحيحان"},{"level":"2–3 درجات","description":"حسابات صحيحة دون استنتاج كامل"},{"level":"1 درجة","description":"حساب فترة واحدة صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة السرعة على الزمن الكلي بدل الفترة","استنتاج أن التسارع يزداد لأن السرعة تزداد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:58.906Z"}'::jsonb)
