from (values
('mcq', 1, 'بحسب ما استنتجه جاليليو، كيف يتأثر تسارع جسم يسقط سقوطًا حرًا (بإهمال مقاومة الهواء) بكتلته ونوع مادته؟', null, null, '["يزداد بزيادة كتلته ولا يتأثر بنوع مادته","لا يتأثر بكتلته ولا بنوع مادته","يتأثر بنوع مادته فقط ولا يتأثر بكتلته","يزداد بزيادة كتلته وبزيادة كثافة مادته"]'::jsonb, 'تذكر', 'تذكر مبدأ', 'سهل', 'الكتاب ص 79 — استنتاج جاليليو: التسارع نفسه لجميع الأجسام الساقطة سقوطًا حرًا'),
('mcq', 2, 'أُسقطت كرتان متماثلتان في الحجم، إحداهما من الألومنيوم والأخرى من الفولاذ، من الارتفاع نفسه في اللحظة نفسها (أهمل مقاومة الهواء). أيّ العبارات الآتية تصف وصولهما إلى الأرض؟', null, null, '["تصل كرة الفولاذ أولًا؛ لأن كتلتها أكبر من كتلة الأخرى","تصل كرة الألومنيوم أولًا؛ لأنها أخف فتتسارع أكثر","تصل كرة الفولاذ أولًا؛ لأن مادتها أكثف","تصلان في اللحظة نفسها؛ لأن لهما التسارع نفسه"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 87 — السؤال 60'),
('mcq', 3, 'أُسقطت ورقتان متماثلتان من الارتفاع نفسه: الأولى مفرودة، والثانية بعد لفّها على شكل كرة متماسكة. لماذا تصل الورقة المكوّرة إلى الأرض أولًا؟', null, null, '["لأن مساحة سطحها أصغر فيقل تأثير مقاومة الهواء فيها","لأن كتلتها أصبحت أكبر بعد لفّها على شكل كرة","لأن التسارع الناتج عن الجاذبية الأرضية للأجسام الكروية أكبر","لأن الجاذبية الأرضية لا تؤثر في الورقة وهي مفرودة"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 79 — الورقة المفرودة والمكوّرة والحصاة'),
('mcq', 4, 'يبين الشكل الآتي صورًا متتالية التُقطت على فترات زمنية متساوية لقطعة نقدية وريشة أُسقطتا معًا داخل أنبوب فيه هواء. إذا فُرّغ الأنبوب من الهواء وأُعيدت التجربة، فما الذي يحدث؟', null, '[{"src":"qimg/phys1/c3l3-o05-tube.svg","alt":"أنبوب رأسي مكتوب فوقه «أنبوب فيه هواء»، وبداخله عمودان من الصور المتتالية الملتقطة على فترات زمنية متساوية. العمود الأيسر لقطعة نقدية (مكتوب أسفله «قطعة نقدية»): ست صور تزداد المسافات بينها بانتظام حتى تصل قرب منتصف الأنبوب السفلي. العمود الأيمن لريشة (مكتوب أسفله «ريشة»): ست صور متقاربة بمسافات صغيرة متساوية تبقى في الجزء العلوي من الأنبوب."}]'::jsonb, '["تصل القطعة النقدية أولًا، لكن بفارق زمني أقل","تصل القطعة النقدية أولًا بالفارق الزمني نفسه","تصل القطعة النقدية والريشة إلى قاع الأنبوب معًا","تبقى الريشة معلّقة لعدم وجود هواء يحملها"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 79 — الأجسام الخفيفة المنبسطة ومقاومة الهواء'),
('mcq', 5, 'في لعبة عربات السقوط الحر تسقط عربة من السكون سقوطًا حرًا مدة 1.5 s، وفيها شخصان كتلتاهما 50 kg و100 kg (أهمل مقاومة الهواء). ما مقدار سرعة كل منهما في نهاية هذه الفترة؟', null, null, '["كل منهما 15 m/s","الأثقل 29 m/s والأخف 15 m/s","الأخف 29 m/s والأثقل 15 m/s","الأثقل 15 m/s والأخف 7.4 m/s"]'::jsonb, 'تطبيق', 'حساب ومقارنة', 'متوسط', 'الكتاب ص 81 — عربات السقوط الحر'),
('mcq', 6, 'في أيّ الحالات الآتية لا يمكن إهمال تأثير مقاومة الهواء في الجسم الساقط؟', null, null, '["كرة فولاذية تسقط من ارتفاع 2 m","حصاة صغيرة تسقط في بئر قليلة العمق","مفتاح معدني يسقط من يد طفل","ورقة شجر جافة تسقط من غصنها"]'::jsonb, 'فهم', 'تطبيق مبدأ على مواقف', 'متوسط', 'الكتاب ص 87 — السؤالان 61 و62'),
('mcq', 7, 'أسقط طالب ثلاثة أجسام من ارتفاع 2.0 m وقاس زمن سقوط كل منها، فحصل على النتائج في الجدول الآتي. أيّ استنتاج تدعمه هذه النتائج؟', '{"headers":["الجسم","الكتلة (kg)","زمن السقوط (s)"],"rows":[["كرة فولاذية","2.0","0.64"],["كرة خشبية","0.50","0.64"],["ورقة مفرودة","0.0050","1.9"]]}'::jsonb, null, '["زمن السقوط يقل كلما زادت كتلة الجسم الساقط من الارتفاع نفسه","الكتلة لا تؤثر في زمن السقوط، وتأخر الورقة سببه مقاومة الهواء","الأجسام الأثقل لها تسارع أكبر من الأجسام الأخف","الورقة تأخرت لأن التسارع الناتج عن الجاذبية لها أصغر"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 79 — استنتاج جاليليو: التسارع نفسه لجميع الأجسام الساقطة سقوطًا حرًا'),
('essay', 1, 'أُسقطت كرتان متماثلتان في الحجم، إحداهما من الألومنيوم والأخرى من الفولاذ، من الارتفاع نفسه في اللحظة نفسها، فوصلتا إلى الأرض في اللحظة نفسها تقريبًا. (أ) فسّر ذلك. (ب) ماذا تتوقع لو استُبدلت بكرة الألومنيوم ورقة صحيفة مفرودة؟ فسّر توقعك.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 79 وص 87 — السؤال 60'),
('essay', 2, 'ورقة مفرودة وورقة أخرى مماثلة لها تمامًا لُفّت على شكل كرة متماسكة، أُسقطتا معًا من الارتفاع نفسه، فوصلت المكوّرة أولًا. (أ) هل اختلاف الكتلة هو سبب هذا الفرق؟ علّل. (ب) ما السبب الحقيقي؟ (ج) ماذا تستنتج من هذه التجربة عن العامل الذي يجعل الأجسام الخفيفة المنبسطة تسقط بطريقة مختلفة؟', null, null, null, 'تحليل', 'تحليل تجربة', 'صعب', 'الكتاب ص 79 — الورقة المفرودة والمكوّرة'),
('essay', 3, 'صمّم تجربة بسيطة تختبر بها صحة العبارة: «جميع الأجسام التي تسقط سقوطًا حرًا لها التسارع نفسه بغض النظر عن كتلتها». حدد الأدوات، والمتغير الذي تغيّره، والمتغيرات التي تثبّتها، وما تقيسه، والنتيجة المتوقعة، وكيف تقلل أثر مقاومة الهواء.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 79 وص 81 — استنتاج جاليليو وعربات السقوط الحر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L3-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'استنتج جاليليو أن جميع الأجسام التي تسقط سقوطًا حرًا لها التسارع نفسه عند إهمال مقاومة الهواء، وأن هذا التسارع لا يتأثر بنوع مادة الجسم أو وزنه.', '["الكتلة لا تؤثر في تسارع السقوط الحر؛ فالجسم الأثقل والأخف يتسارعان بالمقدار نفسه g.","","نوع المادة لا يؤثر في تسارع السقوط الحر أيضًا؛ فكرة الألومنيوم وكرة الفولاذ تصلان معًا.","لا الكتلة ولا كثافة المادة تؤثر في تسارع السقوط الحر عند إهمال مقاومة الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:58.906Z"}'::jsonb),
('mcq', 2, 3, 'الكرتان تسقطان سقوطًا حرًا بالتسارع نفسه g، وتبدآن من السكون ومن الارتفاع نفسه، فتكون سرعتاهما متساويتين في كل لحظة وتصلان معًا.', '["الكتلة الأكبر لا تعني تسارعًا أكبر في السقوط الحر؛ فالتسارع g للجميع.","خفة الكرة لا تجعلها أسرع؛ فتسارعها g مثل الكرة الأثقل.","نوع المادة وكثافتها لا يؤثران في تسارع السقوط الحر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('mcq', 3, 0, 'الورقتان لهما الكتلة نفسها، والجاذبية تكسبهما التسارع نفسه لو أُهمل الهواء. لكن الورقة المفرودة خفيفة ومنبسطة فتصطدم بجزيئات هواء أكثر، وتؤثر مقاومة الهواء في سرعة هبوطها تأثيرًا كبيرًا؛ أما المكوّرة فمساحة سطحها صغيرة فيقل هذا التأثير.', '["","لفّ الورقة لا يغيّر كتلتها؛ فهي الورقة نفسها.","التسارع الناتج عن الجاذبية لا يعتمد على شكل الجسم؛ فالاختلاف سببه مقاومة الهواء.","الجاذبية تؤثر في الورقة المفرودة أيضًا، لكن مقاومة الهواء تبطئ هبوطها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('mcq', 4, 2, 'في الأنبوب الذي فيه هواء تتأخر الريشة لأن مقاومة الهواء تؤثر فيها كثيرًا. بعد التفريغ لا تؤثر فيهما إلا الجاذبية، فتسقطان سقوطًا حرًا بالتسارع نفسه g، فتصلان معًا.', '["بعد التفريغ لا يبقى سبب لأي فارق؛ فالتسارع g للجسمين، والفارق الزمني يختفي تمامًا.","الفارق كان سببه مقاومة الهواء؛ فإذا أُزيل الهواء زال الفارق.","","الهواء لا «يحمل» الريشة؛ بل يبطئ سقوطها، وفي غيابه تسقط بتسارع g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('mcq', 5, 0, 'للشخصين التسارع نفسه g مهما اختلفت كتلتاهما، فسرعة كل منهما $v = gt = 9.80 \times 1.5 = 14.7 \approx 15\ \text{m/s}$ إلى أسفل (رقمان معنويان لأن الزمن 1.5 s).', '["","افتُرض خطأً أن التسارع يتضاعف بتضاعف الكتلة؛ والتسارع في السقوط الحر لا يتأثر بالكتلة.","افتُرض خطأً أن الأخف يتسارع أكثر؛ والتسارع واحد للجميع.","افتُرض أن السرعة تتناسب مع الكتلة فنُصفت سرعة الأخف ($7.35 \\approx 7.4$)؛ والكتلة لا تؤثر في السرعة المكتسبة في السقوط الحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('mcq', 6, 3, 'ورقة الشجر خفيفة ومساحة سطحها كبيرة، فتؤثر مقاومة الهواء في سرعة هبوطها تأثيرًا كبيرًا (تتأرجح وتهبط ببطء)، فلا يمكن عدّ حركتها سقوطًا حرًا.', '["الكرة الفولاذية ثقيلة نسبيًا وصغيرة المساحة، فتأثير الهواء فيها مهمل في ارتفاع صغير.","الحصاة ثقيلة نسبيًا وصغيرة المساحة، فيمكن إهمال مقاومة الهواء فيها.","المفتاح المعدني ثقيل نسبيًا وصغير المساحة، فحركته سقوط حر تقريبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('mcq', 7, 1, 'الكرتان الفولاذية (2.0 kg) والخشبية (0.50 kg) استغرقتا الزمن نفسه 0.64 s رغم اختلاف كتلتيهما ومادتيهما، فالكتلة لا تؤثر في تسارع السقوط الحر. أما الورقة المفرودة فاستغرقت 1.9 s لأنها خفيفة ومنبسطة فتؤثر فيها مقاومة الهواء كثيرًا، لا لأن g لها أصغر.', '["الكرتان مختلفتا الكتلة واستغرقتا الزمن نفسه، فالبيانات لا تدعم أن الزمن يقل بزيادة الكتلة.","","تساوي زمني الكرتين يعني تساوي تسارعيهما رغم اختلاف كتلتيهما.","g واحد لجميع الأجسام؛ وتأخر الورقة سببه مقاومة الهواء التي تؤثر في الأجسام الخفيفة المنبسطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:58.907Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الكرتان ثقيلتان نسبيًا وصغيرتا المساحة، فتأثير مقاومة الهواء فيهما مهمل، فتسقطان سقوطًا حرًا. وجميع الأجسام الساقطة سقوطًا حرًا لها التسارع نفسه g مهما اختلفت كتلتها أو نوع مادتها، فتكون سرعتاهما متساويتين في كل لحظة وتصلان معًا. (ب) تصل كرة الفولاذ أولًا وتتأخر الورقة كثيرًا؛ لأن الورقة خفيفة ومنبسطة فتصطدم بجزيئات الهواء ويؤثر ذلك في سرعة هبوطها تأثيرًا كبيرًا، فلا تكون حركتها سقوطًا حرًا. والسبب مقاومة الهواء لا اختلاف g.', '["التسارع نفسه g للكرتين","لا تأثير للكتلة ونوع المادة","تأخر الورقة","سبب التأخر مقاومة الهواء لا g"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير وصول الكرتين معًا","marks":2},{"element":"توقع سلوك الورقة","marks":1},{"element":"تفسير التوقع بمقاومة الهواء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للجزأين"},{"level":"2–3 درجات","description":"تفسير صحيح لأحد الجزأين مع نقص في الآخر"},{"level":"1 درجة","description":"إجابة صحيحة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفولاذ يصل أولًا لأنه أثقل","تفسير تأخر الورقة بأن g لها أصغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:58.908Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لا؛ لأن الورقتين لهما الكتلة نفسها، فلا يمكن أن يكون الفرق ناتجًا عن الكتلة. (ب) السبب مقاومة الهواء: الورقة المفرودة مساحة سطحها كبيرة فتصطدم بجزيئات هواء أكثر، فيتأثر هبوطها كثيرًا، أما المكوّرة فمساحة سطحها صغيرة فتأثير الهواء فيها أقل. (ج) العامل هو مقاومة الهواء المرتبطة بالشكل ومساحة السطح؛ ولو أُهملت مقاومة الهواء لسقطت الورقتان بالتسارع نفسه g.', '["الكتلتان متساويتان فالكتلة ليست السبب","السبب مقاومة الهواء","دور مساحة السطح","دون الهواء تسقطان بالتسارع نفسه"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة معللة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"تحديد مقاومة الهواء سببًا مع نقص في التعليل"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الورقة المكوّرة أثقل","القول إن الجاذبية لا تؤثر في الورقة المفرودة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:58.908Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأدوات: كرات صغيرة متماثلة الحجم مختلفة الكتلة (فولاذ، زجاج، خشب)، ومسطرة مترية، وساعة إيقاف أو بوابة ضوئية. المتغير المستقل: كتلة الكرة. المتغيرات الثابتة: ارتفاع الإسقاط (مثلًا 2.0 m)، وحجم الكرة وشكلها، والإسقاط من السكون. المقيس: زمن السقوط (عدة مرات وأخذ المتوسط). يمكن إسقاط كرتين معًا ومراقبة وصولهما. النتيجة المتوقعة: زمن السقوط متساوٍ تقريبًا لجميع الكرات (نحو 0.64 s من 2.0 m)، فالتسارع واحد. تقليل أثر الهواء: استخدام أجسام ثقيلة نسبيًا صغيرة المساحة وارتفاع غير كبير، أو إجراء التجربة في أنبوب مفرغ من الهواء.', '["أدوات مناسبة","تغيير الكتلة فقط وتثبيت الارتفاع والشكل","قياس الزمن وتكراره","النتيجة المتوقعة: أزمنة متساوية","تقليل مقاومة الهواء"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات","marks":1},{"element":"ضبط المتغيرات","marks":1},{"element":"القياس","marks":1},{"element":"النتيجة المتوقعة","marks":1},{"element":"تقليل مقاومة الهواء","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم كامل منضبط المتغيرات مع نتيجة متوقعة صحيحة"},{"level":"3–4 درجات","description":"تصميم مناسب ينقصه ضبط متغير أو تقليل أثر الهواء"},{"level":"1–2 درجة","description":"فكرة عامة دون ضبط للمتغيرات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير الكتلة والشكل معًا","استخدام ورقة وحجر للمقارنة","إسقاط الأجسام من ارتفاعات مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:58.908Z"}'::jsonb)
