from (values
('mcq', 1, 'أسقط عامل بناء قطعة قرميد من سطح بناية (أهمل مقاومة الهواء). ما مقدار سرعتها بعد 4.0 s؟', null, null, '["78 m/s","39 m/s","20 m/s","2.5 m/s"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 82 — المسألة 41a'),
('mcq', 2, 'أسقط طالب حجرًا من السكون في بئر، فسمع صوت ارتطامه بالماء بعد 2.5 s. إذا أُهمل زمن انتقال الصوت ومقاومة الهواء، فما عمق سطح الماء تحت نقطة الإسقاط؟', null, null, '["61 m","12 m","25 m","31 m"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 81 — معادلة الإزاحة في السقوط الحر'),
('mcq', 3, 'أسقط طالب كرة من نافذة ترتفع 3.5 m عن الرصيف (أهمل مقاومة الهواء). ما مقدار سرعتها لحظة ملامستها الرصيف؟', null, null, '["8.3 m/s","69 m/s","34 m/s","5.9 m/s"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 82 — المسألة 42'),
('mcq', 4, 'قُذفت كرة رأسيًا إلى أعلى بسرعة ابتدائية 15.0 m/s (أهمل مقاومة الهواء). ما أقصى ارتفاع تصل إليه فوق نقطة القذف؟', null, null, '["23.0 m","1.53 m","11.5 m","45.9 m"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 82 — المسألتان 43a و44'),
('mcq', 5, 'ركل طالب كرة رأسيًا إلى أعلى، فعادت إلى قدمه بعد 3.0 s من لحظة ركلها (أهمل مقاومة الهواء). ما مقدار السرعة الابتدائية للكرة؟', null, null, '["29 m/s","15 m/s","7.4 m/s","0.31 m/s"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 82 — المسألة 48a'),
('mcq', 6, 'سقط أصيص أزهار من شرفة ترتفع 85 m عن أرضية الشارع (أهمل مقاومة الهواء). ما الزمن الذي استغرقه في السقوط حتى اصطدامه بالأرض؟', null, null, '["4.2 s","2.9 s","8.7 s","17 s"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 93 — اختبار مقنن، السؤال 4'),
('mcq', 7, 'قُذفت كرة رأسيًا إلى أسفل بسرعة 2.0 m/s من نافذة منزل كما في الشكل الآتي، ورصيف المشاة يقع على بعد 2.5 m أسفل نقطة القذف (أهمل مقاومة الهواء). ما مقدار سرعة الكرة لحظة وصولها إلى الرصيف؟', null, '[{"src":"qimg/phys1/c3l3-o06-window.svg","alt":"مبنى فيه نافذة، وبجانبها كرة يخرج منها سهم أحمر رأسي إلى أسفل مكتوب بجانبه v_i يمثل سرعتها الابتدائية. على اليمين خط قياس رأسي من مستوى الكرة إلى سطح الأرض مكتوب بجانبه 2.5 m، وتحت المبنى خط يمثل الأرض مكتوب أسفله «رصيف المشاة»."}]'::jsonb, '["7.0 m/s","9.0 m/s","5.3 m/s","7.3 m/s"]'::jsonb, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 90 — السؤال 93'),
('essay', 1, 'يسقط حجر سقوطًا حرًا من السكون (أهمل مقاومة الهواء، واختر الاتجاه الموجب إلى أسفل). احسب: (أ) سرعته المتجهة بعد 8.0 s. (ب) إزاحته خلال هذه المدة.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 90 — السؤال 92'),
('essay', 2, 'قُذفت كرة تنس رأسيًا إلى أعلى بسرعة ابتدائية 22.5 m/s، وأُمسك بها عند عودتها إلى الارتفاع نفسه الذي قُذفت منه (أهمل مقاومة الهواء، واختر الاتجاه الموجب إلى أعلى). (أ) احسب أقصى ارتفاع وصلت إليه الكرة. (ب) احسب الزمن الذي استغرقته الكرة في الهواء.', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 82 — المسألة 43'),
('essay', 3, 'ترتفع طائرة مروحية رأسيًا بسرعة ثابتة 5.0 m/s عندما سقط كيس من حمولتها، فوصل الكيس إلى سطح الأرض بعد 2.0 s (أهمل مقاومة الهواء، واختر الاتجاه الموجب إلى أعلى ونقطة الأصل عند موقع سقوط الكيس). احسب: (أ) السرعة المتجهة للكيس لحظة وصوله إلى الأرض. (ب) إزاحة الكيس، ومنها ارتفاع نقطة سقوطه عن الأرض. (ج) بعد الكيس عن الطائرة لحظة وصوله إلى الأرض.', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 91 — السؤال 102')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
