from (values
('mcq', 1, 1, '$v_f = v_i + gt = 0 + (9.80)(4.0) = 39.2 \approx 39\ \text{m/s}$ (رقمان معنويان لأن الزمن 4.0 s).', '["هذه هي المسافة المقطوعة $\\frac{1}{2}gt^2 = 78.4\\ \\text{m}$ بوحدة خاطئة، وليست السرعة.","","استُخدم $\\frac{1}{2}gt$ خطأً؛ فالمعامل ½ يخص معادلة الموقع لا معادلة السرعة.","قُسمت g على الزمن بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:58.908Z"}'::jsonb),
('mcq', 2, 3, '$d = \frac{1}{2}gt^2 = \frac{1}{2}(9.80)(2.5)^2 = 30.6 \approx 31\ \text{m}$.', '["نُسي المعامل ½: $gt^2 = 61.3\\ \\text{m}$.","نُسي تربيع الزمن: $\\frac{1}{2}gt = 12.25\\ \\text{m}$.","هذا ناتج $gt = 24.5$، وهو مقدار السرعة عند الماء بوحدة m/s لا العمق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:58.909Z"}'::jsonb),
('mcq', 3, 0, '$v_f^2 = v_i^2 + 2gd = 0 + 2(9.80)(3.5) = 68.6$، ومنه $v_f = \sqrt{68.6} = 8.3\ \text{m/s}$.', '["","هذا $v_f^2 = 68.6$؛ فقد نُسي أخذ الجذر التربيعي.","هذا $gd = 34.3$ دون العامل 2 ودون جذر.","هذا $\\sqrt{gd} = 5.9$؛ فقد نُسي العامل 2 تحت الجذر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:58.909Z"}'::jsonb),
('mcq', 4, 2, 'عند أقصى ارتفاع $v_f = 0$. باختيار الموجب إلى أعلى: $0 = v_i^2 + 2(-g)d$، فإن $d = \frac{v_i^2}{2g} = \frac{(15.0)^2}{2(9.80)} = 11.5\ \text{m}$.', '["نُسي العامل 2 في المقام: $\\frac{v_i^2}{g} = 23.0$.","هذا $\\frac{v_i}{g} = 1.53$، وهو زمن الصعود بالثواني لا الارتفاع.","","ضُربت السرعة الابتدائية في زمن التحليق كاملًا: $v_i \\times \\frac{2v_i}{g} = 15.0 \\times 3.06 = 45.9$، وأُهمل أثر التسارع الذي يبطئ الكرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:34:58.909Z"}'::jsonb),
('mcq', 5, 1, 'زمن الصعود يساوي زمن الهبوط، فزمن الصعود 1.5 s. باختيار الموجب إلى أعلى يكون $\boldsymbol{a} = -g$، وعند القمة $v_f = 0$: $0 = v_i - g(1.5)$، فإن $v_i = (9.80)(1.5) = 14.7 \approx 15\ \text{m/s}$.', '["استُخدم الزمن الكلي 3.0 s بدل زمن الصعود: $9.80 \\times 3.0 = 29.4$.","","استُخدم $\\frac{1}{2}g \\times 1.5 = 7.35$؛ والمعامل ½ لا يظهر في معادلة السرعة.","قُسم الزمن على g بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:58.909Z"}'::jsonb),
('mcq', 6, 0, '$d = \frac{1}{2}gt^2$، ومنه $t = \sqrt{\frac{2d}{g}} = \sqrt{\frac{2(85)}{9.80}} = 4.2\ \text{s}$.', '["","نُسي العامل 2: $\\sqrt{\\frac{d}{g}} = 2.9$.","نُسي الجذر والعامل 2: $\\frac{d}{g} = 8.7$.","نُسي الجذر: $\\frac{2d}{g} = 17$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:58.909Z"}'::jsonb),
('mcq', 7, 3, 'باختيار الموجب إلى أسفل: $v_f^2 = v_i^2 + 2gd = (2.0)^2 + 2(9.80)(2.5) = 4.0 + 49 = 53$، ومنه $v_f = 7.3\ \text{m/s}$.', '["أُهملت السرعة الابتدائية: $\\sqrt{2gd} = 7.0$، كأن الكرة أُسقطت من السكون.","جُمعت السرعة الابتدائية مع $\\sqrt{2gd}$ مباشرة: $2.0 + 7.0$؛ والسرع لا تُجمع بهذه الطريقة في هذه المعادلة.","نُسي العامل 2: $\\sqrt{v_i^2 + gd} = 5.3$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:58.910Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{g}t = 0 + (9.80)(8.0) = 78.4 \approx 78\ \text{m/s}$ إلى أسفل. (ب) $\boldsymbol{d}_f = \boldsymbol{v}_i t + \frac{1}{2}\boldsymbol{g}t^2 = \frac{1}{2}(9.80)(8.0)^2 = 313.6 \approx 3.1 \times 10^2\ \text{m}$ إلى أسفل.', '["اختيار المعادلات المناسبة","$\\boldsymbol{v}_f \\approx +78\\ \\text{m/s}$","$\\boldsymbol{d}_f \\approx +3.1 \\times 10^2\\ \\text{m}$","الأرقام المعنوية والوحدات"]'::jsonb, '["المعطيات: $v_i = 0$، $\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$، $t = 8.0\\ \\text{s}$","$\\boldsymbol{v}_f = (9.80)(8.0) = 78.4\\ \\text{m/s} \\approx 78\\ \\text{m/s}$","$\\boldsymbol{d}_f = \\frac{1}{2}(9.80)(8.0)^2 = 313.6\\ \\text{m} \\approx 3.1 \\times 10^2\\ \\text{m}$"]'::jsonb, '[{"element":"المعادلات والمعطيات","marks":1},{"element":"حساب السرعة","marks":1},{"element":"حساب الإزاحة","marks":1},{"element":"الأرقام المعنوية والوحدات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بأرقام معنوية ووحدات صحيحة"},{"level":"2–3 درجات","description":"حساب صحيح لكمية واحدة أو خطأ في الأرقام المعنوية"},{"level":"1 درجة","description":"كتابة المعادلات الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ½ في معادلة الإزاحة","نسيان تربيع الزمن","كتابة الناتج 313.6 m بأرقام معنوية أكثر من المعطيات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:58.910Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عند أقصى ارتفاع $v_f = 0$: $0 = (22.5)^2 + 2(-9.80)d$، فإن $d = \frac{(22.5)^2}{2(9.80)} = 25.8\ \text{m}$. (ب) زمن الصعود: $0 = 22.5 + (-9.80)t$، فإن $t = 2.30\ \text{s}$. وزمن الهبوط يساوي زمن الصعود، فالزمن الكلي في الهواء $2 \times 2.30 = 4.59\ \text{s}$.', '["استخدام $v_f = 0$ عند أقصى ارتفاع","أقصى ارتفاع 25.8 m","زمن الصعود 2.30 s","الزمن الكلي 4.59 s"]'::jsonb, '["$\\boldsymbol{v}_i = +22.5\\ \\text{m/s}$، $\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$، $v_f = 0$ عند القمة","$v_f^2 = v_i^2 + 2ad \\Rightarrow d = \\frac{v_i^2}{2g} = \\frac{506.25}{19.6} = 25.8\\ \\text{m}$","$v_f = v_i + at \\Rightarrow t_{\\text{up}} = \\frac{22.5}{9.80} = 2.30\\ \\text{s}$","$t_{\\text{total}} = 2t_{\\text{up}} = 4.59\\ \\text{s}$"]'::jsonb, '[{"element":"شرط القمة والإشارات","marks":1},{"element":"أقصى ارتفاع","marks":1},{"element":"زمن الصعود","marks":1},{"element":"الزمن الكلي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل"},{"level":"2–3 درجات","description":"حساب أحد الجزأين صحيحًا أو نسيان مضاعفة الزمن"},{"level":"1 درجة","description":"استخدام شرط $v_f = 0$ دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ زمن الصعود هو الزمن الكلي","استخدام $+g$ مع الموجب إلى أعلى فينتج ارتفاع سالب","افتراض أن التسارع صفر عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:34:58.910Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لحظة السقوط تكون سرعة الكيس مساوية لسرعة الطائرة: $\boldsymbol{v}_i = +5.0\ \text{m/s}$. (أ) $\boldsymbol{v}_f = 5.0 + (-9.80)(2.0) = -14.6 \approx -15\ \text{m/s}$، أي 15 m/s إلى أسفل. (ب) $\boldsymbol{d}_f = (5.0)(2.0) + \frac{1}{2}(-9.80)(2.0)^2 = 10 - 19.6 = -9.6\ \text{m}$، فنقطة السقوط على ارتفاع 9.6 m تقريبًا فوق الأرض. (ج) الطائرة صعدت $(5.0)(2.0) = +10\ \text{m}$، فالبعد بينهما $10 - (-9.6) = 19.6\ \text{m}$، أي نحو $2.0 \times 10^1\ \text{m}$ بالتقريب إلى رقمين معنويين. (تُقبل في (أ) $-14.6$ أو $-15\ \text{m/s}$، وفي (ج) 19.6 أو 20 m.)', '["$\\boldsymbol{v}_i$ للكيس $= +5.0\\ \\text{m/s}$","$\\boldsymbol{v}_f \\approx -15\\ \\text{m/s}$","$\\boldsymbol{d}_f \\approx -9.6\\ \\text{m}$","البعد عن الطائرة ≈ 20 m"]'::jsonb, '["$\\boldsymbol{v}_i = +5.0\\ \\text{m/s}$، $\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$، $t = 2.0\\ \\text{s}$","$\\boldsymbol{v}_f = 5.0 - 19.6 = -14.6\\ \\text{m/s}$","$\\boldsymbol{d}_f = 10 - 19.6 = -9.6\\ \\text{m}$","موقع الطائرة بعد 2.0 s: $+10\\ \\text{m}$","البعد $= 10 - (-9.6) = 19.6 \\approx 20\\ \\text{m}$"]'::jsonb, '[{"element":"السرعة الابتدائية للكيس","marks":1},{"element":"حساب (أ)","marks":1},{"element":"حساب (ب)","marks":1},{"element":"حساب (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل مع إشارات صحيحة (يُقبل الناتج مقرّبًا أو غير مقرّب: $-14.6$ أو $-15\\ \\text{m/s}$، و19.6 أو 20 m)"},{"level":"2–3 درجات","description":"جزءان صحيحان أو خطأ في السرعة الابتدائية للكيس"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار $v_i = 0$ للكيس لأنه «سقط»","إهمال إشارة الإزاحة السالبة","نسيان حركة الطائرة عند حساب البعد بينهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:58.910Z"}'::jsonb)
