from (values
('mcq', 1, 'قُذفت كرة رأسيًا إلى أعلى (أهمل مقاومة الهواء). أيّ وصف صحيح لسرعتها المتجهة وتسارعها لحظة وصولها إلى أقصى ارتفاع؟', null, null, '["سرعتها المتجهة صفر، وتسارعها صفر","سرعتها المتجهة صفر، وتسارعها 9.80 m/s² إلى أعلى","سرعتها المتجهة صفر، وتسارعها 9.80 m/s² إلى أسفل","سرعتها المتجهة أكبر ما يمكن، وتسارعها صفر"]'::jsonb, 'فهم', 'وصف حالة', 'سهل', 'الكتاب ص 80–81 — تسارع الكرة عند أقصى ارتفاع'),
('mcq', 2, 'يبين المنحنى الآتي السرعة المتجهة لكرة قُذفت رأسيًا إلى أعلى، والاتجاه الموجب إلى أعلى. متى تصل الكرة إلى أقصى ارتفاع، وما تسارعها عندئذ؟', null, '[{"src":"qimg/phys1/c3l3-o07-vt-top.svg","alt":"منحنى (السرعة المتجهة – الزمن) لكرة قذفت رأسيًا إلى أعلى. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 5.5 كل 0.5. المحور الرأسي: السرعة المتجهة (m/s) مدرّج من −29.4 إلى 29.4 كل 4.9، ومحور الزمن عند السرعة صفر. خط مستقيم هابط يبدأ من (0 s، 24.5 m/s) ويقطع محور الزمن عند (2.5 s، 0 m/s) وينتهي عند (5.0 s، −24.5 m/s)."}]'::jsonb, '["عند 2.5 s، وتسارعها $0.00\\ \\text{m/s}^2$","عند 2.5 s، وتسارعها $-9.80\\ \\text{m/s}^2$","عند 5.0 s، وتسارعها $-9.80\\ \\text{m/s}^2$","عند 0.0 s، وتسارعها $+9.80\\ \\text{m/s}^2$"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 80 — الشكل 3-15'),
('mcq', 3, 'يعتقد بعض الطلاب أن تسارع الكرة المقذوفة رأسيًا إلى أعلى يساوي صفرًا عند أقصى ارتفاع. لو كان ذلك صحيحًا، فماذا يحدث للكرة بعد وصولها إلى أقصى ارتفاع؟', null, null, '["تبقى معلّقة في الهواء؛ لأن سرعتها المتجهة لن تتغير عن الصفر","تسقط إلى أسفل بسرعة ثابتة مقدارها 9.80 m/s","تواصل الصعود إلى أعلى بسرعة ثابتة","تسقط إلى أسفل بتسارع أكبر من 9.80 m/s²"]'::jsonb, 'تحليل', 'استدلال', 'متوسط', 'الكتاب ص 80–81 — تسارع الكرة عند أقصى ارتفاع'),
('mcq', 4, 'يبين الشكل الآتي مسار كرة قُذفت رأسيًا إلى أعلى ثم عادت (رُسم الصعود والهبوط متجاورين للتوضيح)، والنقاط: 1 في أثناء الصعود، و2 عند أقصى ارتفاع، و3 في أثناء الهبوط. أيّ وصف صحيح لتسارع الكرة عند النقاط الثلاث؟', null, '[{"src":"qimg/phys1/c3l3-o07-path.svg","alt":"مسار متقطع لكرة قذفت رأسيًا إلى أعلى ثم عادت إلى أسفل، مرسوم على شكل مسارين رأسيين متجاورين يصلهما منحنى صغير في الأعلى. النقطة 1 على المسار الأيسر مكتوب تحتها «صاعدة»، والنقطة 2 عند قمة المسار، والنقطة 3 على المسار الأيمن عند ارتفاع النقطة 1 نفسه مكتوب تحتها «هابطة». في الأسفل خط يمثل الأرض، وعلى اليسار سهم رأسي إلى أعلى مكتوب عنده +y."}]'::jsonb, '["إلى أعلى عند 1، وصفر عند 2، وإلى أسفل عند 3","إلى أسفل عند 1 و3، وصفر عند 2","إلى أعلى عند 1 و2، وإلى أسفل عند 3","إلى أسفل عند النقاط الثلاث 1 و2 و3"]'::jsonb, 'تحليل', 'وصف متجهات', 'متوسط', 'الكتاب ص 80–82 — قذف كرة إلى أعلى، والمراجعة 46'),
('mcq', 5, 'إذا كانت السرعة المتجهة لجسم تساوي صفرًا عند لحظة ما، فهل يجب أن يساوي تسارعه صفرًا عند تلك اللحظة؟', null, null, '["نعم؛ لأن التسارع يساوي السرعة مقسومة على الزمن","نعم؛ لأن الجسم الساكن لا يمكن أن يتسارع","لا؛ فالكرة عند أقصى ارتفاع سرعتها صفر وتسارعها g إلى أسفل","لا؛ لأن تسارعه عندئذ يكون أكبر من g"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 87 — السؤال 66'),
('mcq', 6, 'يبين المنحنى الآتي موقع كرة قُذفت رأسيًا إلى أعلى مع الزمن (الموجب إلى أعلى). ما ميل المماس للمنحنى عند النقطة (2.0 s، 19.6 m)؟', null, '[{"src":"qimg/phys1/c3l3-o07-dt.svg","alt":"منحنى (الموقع – الزمن) لكرة قذفت رأسيًا إلى أعلى. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 4.5 كل 0.5. المحور الرأسي: الموقع (m) مدرّج من 0 إلى 24 كل 4. المنحنى قوس أخضر يبدأ من (0 s، 0 m) ويرتفع حتى قمة معلّمة بنقطة مكتوب عندها (2.0, 19.6) أي عند 2.0 s و19.6 m، ثم ينخفض متماثلًا حتى (4.0 s، 0 m)."}]'::jsonb, '["$0.00\\ \\text{m/s}$","$+19.6\\ \\text{m/s}$","$+9.80\\ \\text{m/s}$","$-9.80\\ \\text{m/s}$"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 80 — الشكل 3-15c'),
('mcq', 7, 'قُذفت كرة رأسيًا إلى أعلى، واختير الاتجاه الموجب إلى أعلى (أهمل مقاومة الهواء). ما سرعتها المتجهة وتسارعها بعد 1.0 s من وصولها إلى أقصى ارتفاع؟', null, null, '["$\\boldsymbol{v} = 0.00\\ \\text{m/s}$ و$\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$","$\\boldsymbol{v} = +9.80\\ \\text{m/s}$ و$\\boldsymbol{a} = +9.80\\ \\text{m/s}^2$","$\\boldsymbol{v} = -9.80\\ \\text{m/s}$ و$\\boldsymbol{a} = 0.00\\ \\text{m/s}^2$","$\\boldsymbol{v} = -9.80\\ \\text{m/s}$ و$\\boldsymbol{a} = -9.80\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب وتحليل', 'صعب', 'الكتاب ص 80–81 — تسارع الكرة عند أقصى ارتفاع'),
('essay', 1, 'افترض أنك قذفت كرة رأسيًا إلى أعلى (أهمل مقاومة الهواء). صف التغيرات في كل من سرعتها المتجهة وتسارعها: (أ) في أثناء الصعود، (ب) عند أقصى ارتفاع، (ج) في أثناء الهبوط.', null, null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 82 — المراجعة 46'),
('essay', 2, 'عند قذف كرة رأسيًا إلى أعلى تكون سرعتها المتجهة اللحظية عند أقصى ارتفاع صفرًا. هل تسارعها عند أقصى ارتفاع صفر؟ أجب، ثم صمّم تجربة تثبت بها صحة إجابتك، محددًا الأدوات وما تقيسه وكيف تحلل النتائج.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 82 — المراجعة 49'),
('essay', 3, 'يبين المنحنى الآتي السرعة المتجهة لكرة قُذفت رأسيًا إلى أعلى، والاتجاه الموجب إلى أعلى. (أ) حدد اللحظة التي تصل فيها الكرة إلى أقصى ارتفاع، مع التعليل. (ب) احسب أقصى ارتفاع وصلت إليه الكرة. (ج) احسب تسارع الكرة عند لحظة أقصى ارتفاع، وفسّر لماذا لا يساوي صفرًا.', null, '[{"src":"qimg/phys1/c3l3-o07-essay-vt.svg","alt":"منحنى (السرعة المتجهة – الزمن) لكرة قذفت رأسيًا إلى أعلى. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 4.5 كل 0.5. المحور الرأسي: السرعة المتجهة (m/s) مدرّج من −24.5 إلى 24.5 كل 4.9، ومحور الزمن عند السرعة صفر. خط مستقيم هابط يبدأ من (0 s، 19.6 m/s) ويقطع محور الزمن عند (2.0 s، 0 m/s) وينتهي عند (4.0 s، −19.6 m/s)."}]'::jsonb, null, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 80 — الشكل 3-15')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L3-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'عند أقصى ارتفاع تتوقف الكرة لحظيًا فتكون سرعتها المتجهة صفرًا، لكن الجاذبية ما زالت تؤثر فيها، فتسارعها g = 9.80 m/s² إلى أسفل كما في كل نقطة من مسارها.', '["هذا هو الخطأ الشائع؛ فلو كان التسارع صفرًا لبقيت السرعة صفرًا وبقيت الكرة معلّقة في الهواء.","تسارع الجاذبية إلى أسفل دائمًا، ولا يصبح إلى أعلى عند القمة.","","السرعة عند أقصى ارتفاع أقل ما يمكن (صفر) لا أكبر ما يمكن، والتسارع لا يساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:58.911Z"}'::jsonb),
('mcq', 2, 1, 'تصل الكرة إلى أقصى ارتفاع عندما تصبح سرعتها المتجهة صفرًا، أي حيث يقطع الخط محور الزمن عند 2.5 s. والتسارع هو ميل الخط، وهو ثابت عند كل نقطة: $\frac{-24.5 - 24.5}{5.0 - 0} = -9.80\ \text{m/s}^2$، بما في ذلك لحظة أقصى ارتفاع.', '["الميل عند 2.5 s لا يساوي صفرًا؛ فالخط مستقيم وميله ثابت $-9.80\\ \\text{m/s}^2$ عند كل نقطة.","","عند 5.0 s تكون السرعة $-24.5\\ \\text{m/s}$، أي أن الكرة عادت إلى نقطة القذف لا أنها في أقصى ارتفاع.","عند 0.0 s تكون الكرة عند نقطة القذف بأكبر سرعة صعود، والتسارع سالب لا موجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:58.911Z"}'::jsonb),
('mcq', 3, 0, 'التسارع معدل تغير السرعة المتجهة؛ فإذا كان صفرًا عند لحظة كانت فيها السرعة صفرًا، فلن تتغير السرعة وستبقى 0.0 m/s، أي ستبقى الكرة معلّقة. ولأن الكرات لا تبقى معلّقة، نستنتج أن تسارعها عند أقصى ارتفاع لا يساوي صفرًا واتجاهه إلى أسفل.', '["","لكي تكتسب الكرة أي سرعة إلى أسفل يجب أن تتغير سرعتها، وهذا يتطلب تسارعًا لا يساوي صفرًا.","سرعة الكرة عند القمة صفر، ومع تسارع صفري لا تكتسب أي سرعة إلى أعلى.","افتراض التسارع صفرًا يناقض اكتساب أي تسارع بعد ذلك؛ فهذا البديل يخالف الفرض نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:58.911Z"}'::jsonb),
('mcq', 4, 3, 'تتغير السرعة المتجهة من أعلى (في الصعود عند 1) إلى صفر (عند القمة 2) إلى أسفل (في الهبوط عند 3)، أما التسارع فهو التسارع الناتج عن الجاذبية الأرضية، ثابت ومتجه إلى أسفل عند جميع النقاط بما فيها القمة.', '["التسارع لا يتبع اتجاه السرعة؛ فهو إلى أسفل حتى في أثناء الصعود، ولا يصبح صفرًا عند القمة.","التسارع لا يصبح صفرًا عند القمة؛ فلو كان صفرًا لبقيت الكرة معلّقة هناك.","التسارع إلى أسفل عند النقطة 1 أيضًا، والكرة لا تعود إلى أعلى عند 2؛ والتسارع لا يتبع موقع الكرة ولا اتجاه حركتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:58.911Z"}'::jsonb),
('mcq', 5, 2, 'السرعة الصفرية لحظيًا لا تعني تسارعًا صفريًا؛ فالتسارع يصف تغير السرعة. الكرة المقذوفة إلى أعلى سرعتها صفر عند أقصى ارتفاع، لكن سرعتها تتغير من موجبة إلى سالبة، فتسارعها g = 9.80 m/s² إلى أسفل.', '["التسارع هو التغير في السرعة مقسومًا على الفترة الزمنية، لا السرعة نفسها مقسومة على الزمن.","الجسم الساكن لحظيًا يمكن أن يتسارع، كالكرة عند القمة التي تبدأ فورًا بالهبوط.","","الجواب «لا» صحيح، لكن التعليل خاطئ؛ فتسارع الكرة عند القمة يساوي g تمامًا لا أكبر منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb),
('mcq', 6, 0, 'ميل المماس لمنحنى (الموقع – الزمن) هو السرعة المتجهة اللحظية. عند قمة المنحنى (أقصى ارتفاع) يكون المماس أفقيًا فميله $0.00\ \text{m/s}$، أي أن سرعة الكرة صفر. ومع ذلك فالمنحنى منحنٍ (يتغير ميله من موجب إلى سالب)، أي أن التسارع لا يساوي صفرًا بل $-9.80\ \text{m/s}^2$.', '["","هذا هو الموقع (19.6 m) عند القمة، وليس ميل المماس.","هذا مقدار التسارع بوحدة سرعة؛ وميل منحنى الموقع يعطي السرعة لا التسارع.","هذه قيمة التسارع (بوحدة خاطئة)؛ أما ميل منحنى الموقع عند القمة فيمثل السرعة وهي صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb),
('mcq', 7, 3, 'عند أقصى ارتفاع $v = 0$، وبعده: $\boldsymbol{v}_f = 0 + (-9.80)(1.0) = -9.80\ \text{m/s}$ (إلى أسفل). والتسارع ثابت طوال الحركة $\boldsymbol{a} = -9.80\ \text{m/s}^2$.', '["السرعة صفر لحظة القمة فقط؛ وبعد 1.0 s تكون قد تغيرت بفعل التسارع.","الكرة تهبط بعد القمة فسرعتها سالبة في هذا النظام، والتسارع إلى أسفل فهو سالب كذلك.","التسارع لا يصبح صفرًا بعد القمة؛ فلو كان صفرًا لما تغيرت السرعة من الصفر إلى $-9.80\\ \\text{m/s}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في الصعود: السرعة المتجهة إلى أعلى ويتناقص مقدارها بمعدل 9.80 m/s كل ثانية، والتسارع g إلى أسفل (عكس السرعة؛ لذلك تتباطأ). (ب) عند أقصى ارتفاع: السرعة المتجهة صفر لحظيًا، والتسارع ما زال g = 9.80 m/s² إلى أسفل وليس صفرًا. (ج) في الهبوط: السرعة المتجهة إلى أسفل ويزداد مقدارها 9.80 m/s كل ثانية، والتسارع g إلى أسفل (في اتجاه السرعة؛ لذلك تتسارع). أي أن التسارع ثابت مقدارًا واتجاهًا طوال الحركة، والذي يتغير هو السرعة.', '["الصعود: سرعة إلى أعلى تتناقص","القمة: سرعة صفر","القمة: التسارع g إلى أسفل","الهبوط: سرعة إلى أسفل تتزايد","التسارع ثابت طوال الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"الصعود","marks":1},{"element":"السرعة عند القمة","marks":1},{"element":"التسارع عند القمة","marks":1},{"element":"الهبوط","marks":1},{"element":"ثبات التسارع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح كامل للمراحل الثلاث"},{"level":"3–4 درجات","description":"وصف صحيح مع خطأ في عنصر واحد"},{"level":"1–2 درجة","description":"وصف السرعة فقط دون التسارع"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسارع صفر عند القمة","جعل التسارع إلى أعلى في أثناء الصعود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الإجابة: لا؛ تسارعها عند أقصى ارتفاع يساوي g = 9.80 m/s² إلى أسفل. التجربة: الأدوات: كرة، وكاشف للحركة متصل بحاسوب (أو تصوير فيديو بجانب مسطرة مترية مع تحليل الصور الإطار تلو الآخر). الخطوات: يوضع الكاشف على الأرض متجهًا إلى أعلى (أو تُصوّر الحركة)، وتُقذف الكرة رأسيًا فوقه، ويُسجل موقعها وسرعتها المتجهة على فترات زمنية صغيرة متساوية. التحليل: يُرسم منحنى (السرعة المتجهة – الزمن)؛ فيظهر خطًا مستقيمًا يقطع محور الزمن عند لحظة أقصى ارتفاع دون أن ينكسر أو يصبح أفقيًا عندها، وميله ثابت تقريبًا $-9.80\ \text{m/s}^2$ (مع الموجب إلى أعلى) قبل القمة وعندها وبعدها. كما أن السرعة تتغير من موجبة قبل القمة إلى سالبة بعدها، وتغيّر السرعة يعني وجود تسارع.', '["التسارع عند القمة ليس صفرًا بل g إلى أسفل","أدوات مناسبة لقياس السرعة مع الزمن","رسم منحنى (السرعة المتجهة – الزمن)","الميل ثابت لا يساوي صفرًا عند القمة","تغير إشارة السرعة دليل على التسارع"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة الصحيحة","marks":1},{"element":"الأدوات والإجراء","marks":2},{"element":"طريقة التحليل","marks":1},{"element":"الاستنتاج من الميل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة صحيحة وتصميم كامل وتحليل صحيح"},{"level":"3–4 درجات","description":"إجابة صحيحة وتصميم مناسب ينقصه وضوح التحليل"},{"level":"1–2 درجة","description":"إجابة صحيحة دون تصميم مناسب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاستدلال بأن السرعة صفر فالتسارع صفر","قياس أقصى ارتفاع فقط دون قياس تغير السرعة مع الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عند 2.0 s؛ لأن السرعة المتجهة عندها صفر (الخط يقطع محور الزمن)، فالكرة توقفت لحظيًا عن الصعود. (ب) أقصى ارتفاع = المساحة تحت المنحنى من 0 إلى 2.0 s: $\frac{1}{2}(2.0)(19.6) = 19.6\ \text{m}$. (ج) التسارع = ميل الخط، وهو ثابت عند جميع النقاط: $\frac{-19.6 - 19.6}{4.0 - 0} = -9.80\ \text{m/s}^2$، أي 9.80 m/s² إلى أسفل. لا يساوي صفرًا لأن السرعة تستمر في التغير عبر لحظة القمة من موجبة إلى سالبة، والخط لا ينكسر ولا يصبح أفقيًا عندها.', '["القمة عند 2.0 s حيث v = 0","الارتفاع = المساحة = 19.6 m","التسارع = الميل = $-9.80\\ \\text{m/s}^2$","التسارع لا يساوي صفرًا لاستمرار تغير السرعة"]'::jsonb, '["$v = 0$ عند $t = 2.0\\ \\text{s}$","$d = \\frac{1}{2} \\times 2.0 \\times 19.6 = 19.6\\ \\text{m}$","$\\boldsymbol{a} = \\frac{\\Delta \\boldsymbol{v}}{\\Delta t} = \\frac{-19.6 - 19.6}{4.0} = -9.80\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"حساب التسارع","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات وحسابات صحيحة مع تفسير"},{"level":"2–3 درجات","description":"جزءان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة أقصى ارتفاع من المحور الرأسي (19.6 m/s) بدل حساب المساحة","القول إن الميل صفر عند نقطة التقاطع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:58.912Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L3-O07') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L3-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تجربة تعيين g بالمؤقت ذي الشريط، كان الزمن الدوري للمؤقت (الزمن بين نقطتين متتاليتين) 0.020 s. رُقّمت النقاط ابتداءً من نقطة اختيرت صفرًا: 0، 1، 2، ... ما الزمن الكلي المرتبط بالنقطة رقم 5؟', null, null, '["0.12 s","0.10 s","0.080 s","0.0040 s"]'::jsonb, 'تطبيق', 'إجراء عملي', 'سهل', 'الكتاب ص 84–85 — مختبر الفيزياء: التسارع الناتج عن الجاذبية الأرضية'),
('mcq', 2, 'حصل طالب في تجربة المؤقت ذي الشريط على قيمة تجريبية لـ g مقدارها 9.65 m/s². ما الخطأ النسبي في قيمته مقارنة بالقيمة المقبولة 9.80 m/s²؟', null, null, '["1.6%","0.015%","98%","1.5%"]'::jsonb, 'تطبيق', 'حساب الخطأ النسبي', 'سهل', 'الكتاب ص 85 — الاستنتاج والتطبيق 2'),
('mcq', 3, 'في تجربة المؤقت ذي الشريط (الاتجاه الموجب إلى أسفل) حُسبت قيمة $\frac{\boldsymbol{d}_f}{t_f}$ لكل نقطة ومُثّلت مقابل الزمن $t_f$، ورُسم أفضل خط مستقيم كما في الشكل الآتي، علمًا بأن $\frac{\boldsymbol{d}_f}{t_f} = \boldsymbol{v}_i + \frac{1}{2}\boldsymbol{g}\,t_f$. ما القيمة التجريبية لـ g؟', null, '[{"src":"qimg/phys1/c3l3-o08-fit1.svg","alt":"تمثيل بياني لبيانات تجربة المؤقت ذي الشريط. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 0.45 كل 0.05. المحور الرأسي: d_f / t_f بوحدة m/s مدرّج من 0 إلى 3 كل 0.5. ست نقاط مقيسة مفرّغة تقريبًا على الخط عند الأزمنة 0.10 و0.15 و0.20 و0.25 و0.30 و0.35 s. أفضل خط مستقيم يبدأ من النقطة المعلّمة (0, 0.50) على المحور الرأسي وينتهي عند النقطة المعلّمة (0.40, 2.44)."}]'::jsonb, '["9.70 m/s²","4.85 m/s²","6.10 m/s²","2.43 m/s²"]'::jsonb, 'تطبيق', 'استخدام رسم بياني', 'متوسط', 'الكتاب ص 84–85 — ميل المنحنى يساوي ½a'),
('mcq', 4, 'في تجربة تعيين g بالمؤقت ذي الشريط (الاتجاه الموجب إلى أسفل)، مُثّلت قيم $\frac{\boldsymbol{d}_f}{t_f}$ مقابل الزمن $t_f$ فكان الخط مستقيمًا لا يمر بنقطة الأصل. وفق العلاقة $\frac{\boldsymbol{d}_f}{t_f} = \boldsymbol{v}_i + \frac{1}{2}\boldsymbol{g}\,t_f$، ماذا تمثل نقطة تقاطع الخط مع المحور الرأسي؟', null, null, '["التسارع الناتج عن الجاذبية الأرضية $\\boldsymbol{g}$","نصف التسارع الناتج عن الجاذبية $\\frac{1}{2}g$","السرعة المتجهة الابتدائية $\\boldsymbol{v}_i$ للكتلة","الإزاحة الكلية للكتلة خلال زمن القياس"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'سهل', 'الكتاب ص 84–85 — السرعة الابتدائية من نقطة التقاطع مع المحور الرأسي'),
('mcq', 5, 'في تجربة المؤقت ذي الشريط يُطلب اختيار نقطة البداية «0» على بعد بضعة سنتمترات من أول نقطة طبعها المؤقت. ما الفائدة من ذلك؟', null, null, '["النقاط الأولى متقاربة جدًا ومتداخلة فيصعب قياس المسافات بينها بدقة","التسارع الناتج عن الجاذبية يكون صفرًا في بداية سقوط الكتلة","لكي تكون السرعة المتجهة الابتدائية عند النقطة 0 صفرًا تمامًا","المؤقت لا يطبع النقاط على فترات زمنية متساوية في البداية"]'::jsonb, 'فهم', 'تفسير إجراء', 'متوسط', 'الكتاب ص 85 — التوسع في البحث'),
('mcq', 6, 'يبين الشكل الآتي شريط مؤقت ذي شريط مربوطًا بكتلة تسقط سقوطًا حرًا، والنقاط مرقمة بالترتيب الذي طُبعت به. بين أيّ نقطتين اصطدمت الكتلة بالأرض تقريبًا؟', null, '[{"src":"qimg/phys1/c3l3-o08-tape.svg","alt":"شريط ورقي أفقي عليه عشر نقاط مرقّمة من 0 إلى 9 من اليسار إلى اليمين. المسافات بين النقاط المتتالية تزداد بانتظام من 0 إلى 6 (أكبر مسافة بين 5 و6)، ثم تتناقص: المسافة بين 6 و7 أصغر من التي قبلها، وبين 7 و8 أصغر، وبين 8 و9 أصغر منها جميعًا."}]'::jsonb, '["بين النقطتين 8 و9","بين النقطتين 0 و1","بين النقطتين 6 و7","بين النقطتين 4 و5"]'::jsonb, 'تطبيق', 'تحليل شريط المؤقت', 'متوسط', 'الكتاب ص 85 — الخطوة 8'),
('mcq', 7, 'في تجربة المؤقت ذي الشريط كانت المسافة بين نقطتين متتاليتين 4.2 cm، والزمن الدوري للمؤقت 0.020 s. ما السرعة المتوسطة للكتلة خلال هذه الفترة بوحدة m/s؟', null, null, '["21 m/s","2.1 m/s","0.21 m/s","0.084 m/s"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 85 — التحليل 1'),
('essay', 1, 'سجّل طالب في تجربة المؤقت ذي الشريط (الاتجاه الموجب إلى أسفل) البيانات في الجدول الآتي (المسافة من النقطة 0 والزمن المرتبط بها). (أ) احسب $\frac{\boldsymbol{d}_f}{t_f}$ بوحدة m/s لكل نقطة (وهي السرعة المتجهة المتوسطة من النقطة 0 حتى تلك النقطة). (ب) إذا مثّلت $\frac{\boldsymbol{d}_f}{t_f}$ مقابل $t_f$ فكيف تجد g من الخط؟ احسب g باستخدام النقطتين الأولى والأخيرة. (ج) احسب الخطأ النسبي مقارنة بالقيمة المقبولة 9.80 m/s². (د) قدّر السرعة الابتدائية $\boldsymbol{v}_i$ عند النقطة 0.', '{"headers":["النقطة","الزمن $t_f$ (s)","المسافة $d_f$ (cm)"],"rows":[["1","0.10","8.9"],["2","0.20","27.5"],["3","0.30","55.9"],["4","0.40","94.1"],["5","0.50","142.0"]]}'::jsonb, null, null, 'تطبيق', 'تحليل بيانات تجريبية', 'صعب', 'الكتاب ص 85 — التحليل والاستنتاج'),
('essay', 2, 'اكتب خطوات تعيين التسارع الناتج عن الجاذبية الأرضية عمليًا باستخدام المؤقت ذي الشريط وكتلة 1 kg، من تثبيت الأدوات حتى الحصول على البيانات، واذكر احتياطًا واحدًا للسلامة.', null, null, null, 'تطبيق', 'وصف إجراء', 'متوسط', 'الكتاب ص 84–85 — مختبر الفيزياء: التسارع الناتج عن الجاذبية الأرضية'),
('essay', 3, 'يبين الشكل الآتي التمثيل البياني لقيم $\frac{\boldsymbol{d}_f}{t_f}$ مقابل $t_f$ في تجربة لتعيين g بالمؤقت ذي الشريط (الاتجاه الموجب إلى أسفل)، مع أفضل خط مستقيم. (أ) استخرج من الخط السرعة الابتدائية $\boldsymbol{v}_i$. (ب) احسب القيمة التجريبية لـ g. (ج) احسب الخطأ النسبي. (د) اقترح سببين لكون القيمة التجريبية أصغر من 9.80 m/s².', null, '[{"src":"qimg/phys1/c3l3-o08-fit2.svg","alt":"تمثيل بياني لبيانات تجربة المؤقت ذي الشريط. المحور الأفقي: الزمن (s) مدرّج من 0 إلى 0.55 كل 0.05. المحور الرأسي: d_f / t_f بوحدة m/s مدرّج من 0 إلى 3 كل 0.3. خمس نقاط مقيسة مفرّغة عند الأزمنة 0.10 و0.20 و0.30 و0.40 و0.50 s قريبة من الخط. أفضل خط مستقيم يبدأ من (0 s، 0.30 m/s) على المحور الرأسي ويمر بنقطة الشبكة (0.50 s، 2.70 m/s)."}]'::jsonb, null, 'تحليل', 'تحليل رسم بياني تجريبي', 'صعب', 'الكتاب ص 85 — التحليل 2–3 والاستنتاج 1–2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L3-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'بين النقطة 0 والنقطة 5 خمس فترات، كل منها 0.020 s، فالزمن $5 \times 0.020 = 0.10\ \text{s}$.', '["عُدّت النقاط ست (من 0 إلى 5) بدل الفترات الخمس: $6 \\times 0.020$.","","عُدّت الفترات أربعًا بدل خمس: $4 \\times 0.020$.","قُسم الزمن الدوري على 5 بدل ضربه فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:58.913Z"}'::jsonb),
('mcq', 2, 3, 'الخطأ النسبي $= \frac{|9.80 - 9.65|}{9.80} \times 100\% = \frac{0.15}{9.80} \times 100\% = 1.5\%$.', '["قُسم الفرق على القيمة التجريبية 9.65 بدل القيمة المقبولة.","نُسي الضرب في 100% (الناتج 0.015 كسرًا عشريًا لا نسبة مئوية).","قُسمت القيمة التجريبية على المقبولة ($\\frac{9.65}{9.80} = 98\\%$) بدل قسمة الفرق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:58.913Z"}'::jsonb),
('mcq', 3, 0, 'الميل $= \frac{2.44 - 0.50}{0.40 - 0} = 4.85\ \text{m/s}^2$، والميل يساوي $\frac{1}{2}g$، فإن $g = 2 \times 4.85 = 9.70\ \text{m/s}^2$.', '["","هذا الميل نفسه، وهو $\\frac{1}{2}g$؛ فقد نُسي ضربه في 2.","قُسمت قراءة نقطة واحدة على زمنها $\\frac{2.44}{0.40}$ دون طرح المقطع 0.50، فهذا ليس الميل.","قُسم الميل على 2 بدل ضربه في 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:58.913Z"}'::jsonb),
('mcq', 4, 2, 'عند $t_f = 0$ تصبح العلاقة $\frac{\boldsymbol{d}_f}{t_f} = \boldsymbol{v}_i$؛ فالمقطع الرأسي يساوي السرعة المتجهة الابتدائية للكتلة عند النقطة التي اختيرت صفرًا، وهي لا تساوي صفرًا لأن الكتلة كانت قد بدأت السقوط قبلها.', '["g لا يُقرأ من المقطع؛ بل يساوي ضعف الميل.","$\\frac{1}{2}g$ هو الميل لا المقطع.","","الإزاحة لا تُقرأ من هذا المحور؛ فالمحور الرأسي يمثل $\\frac{\\boldsymbol{d}_f}{t_f}$ بوحدة m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:58.914Z"}'::jsonb),
('mcq', 5, 0, 'في بداية السقوط تكون السرعة صغيرة جدًا، فتكون النقاط الأولى متقاربة ومتداخلة يصعب تمييزها وقياس المسافات بينها، فيُبدأ القياس من نقطة أوضح؛ ولهذا تكون للكتلة سرعة ابتدائية عند النقطة 0 تظهر في المقطع الرأسي.', '["","الكتلة تتسارع بـ g منذ لحظة إفلاتها؛ فالتسارع ليس صفرًا في البداية.","العكس صحيح؛ فبدء القياس من نقطة لاحقة يجعل السرعة الابتدائية عند النقطة 0 لا تساوي صفرًا.","المؤقت يطبع النقاط بزمن دوري ثابت طوال التجربة؛ وهذا أساس حساب الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:58.914Z"}'::jsonb),
('mcq', 6, 2, 'في أثناء السقوط الحر تزداد المسافة بين النقاط المتتالية باستمرار (حتى المسافة بين 5 و6). وتبدأ المسافة بالتناقص بين 6 و7، وتناقص المسافات يعني أن الكتلة اصطدمت بالأرض وتوقفت عن السقوط الحر.', '["التناقص بدأ قبل ذلك؛ فالمسافة بين 6 و7 أصغر من المسافة بين 5 و6.","المسافات تزداد بعد النقطة 1، فالكتلة كانت ما تزال تسقط سقوطًا حرًا.","","المسافات تستمر في الزيادة بعد النقطة 5، فالكتلة لم تصطدم بعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:58.914Z"}'::jsonb),
('mcq', 7, 1, '$\bar{v} = \frac{4.2\ \text{cm}}{0.020\ \text{s}} = 210\ \text{cm/s} = 2.1\ \text{m/s}$ (لأن 100 cm = 1 m).', '["خطأ في التحويل: قُسم 210 cm/s على 10 بدل 100.","","خطأ في التحويل: قُسم 210 cm/s على 1000 بدل 100.","ضُربت المسافة في الزمن ($4.2 \\times 0.020 = 0.084$) بدل قسمتها عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:58.914Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\frac{\boldsymbol{d}_f}{t_f}$: 0.89، 1.38، 1.86، 2.35، 2.84 m/s. (ب) الخط مستقيم وميله $\frac{1}{2}g$: الميل $= \frac{2.84 - 0.89}{0.50 - 0.10} = 4.88\ \text{m/s}^2$، فإن $g = 2 \times 4.88 \approx 9.75\ \text{m/s}^2$. (ج) الخطأ النسبي $= \frac{9.80 - 9.75}{9.80} \times 100\% \approx 0.5\%$. (د) من المقطع: $\boldsymbol{v}_i = 0.89 - 4.88 \times 0.10 \approx 0.40\ \text{m/s}$.', '["تحويل cm إلى m وحساب النسب","الميل = ½g","g ≈ 9.75 m/s²","الخطأ النسبي ≈ 0.5%","$\\boldsymbol{v}_i \\approx 0.40\\ \\text{m/s}$"]'::jsonb, '["$\\frac{0.089}{0.10} = 0.89$، $\\frac{0.275}{0.20} = 1.38$، $\\frac{0.559}{0.30} = 1.86$، $\\frac{0.941}{0.40} = 2.35$، $\\frac{1.420}{0.50} = 2.84\\ \\text{m/s}$","الميل $= \\frac{2.84 - 0.89}{0.40} = 4.875 \\approx 4.88\\ \\text{m/s}^2$","$g = 2 \\times 4.875 = 9.75\\ \\text{m/s}^2$","الخطأ النسبي $= \\frac{0.05}{9.80} \\times 100\\% \\approx 0.5\\%$","$\\boldsymbol{v}_i = 0.89 - (4.875)(0.10) \\approx 0.40\\ \\text{m/s}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) الميل وg","marks":2},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة كاملة (يُقبل g بين 9.74 و9.76 m/s² بحسب تقريب الحسابات الوسيطة، والخطأ النسبي نحو 0.5%)"},{"level":"3–4 درجات","description":"حساب g صحيح مع خطأ في الخطأ النسبي أو في vi"},{"level":"1–2 درجة","description":"حساب النسب فقط أو الميل دون مضاعفته"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الميل هو g دون ضربه في 2","نسيان تحويل cm إلى m","القسمة على القيمة التجريبية في الخطأ النسبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:58.914Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوات: (1) يُثبت المؤقت في حافة طاولة المختبر بماسك على شكل حرف C. (2) يُعيَّن الزمن الدوري للمؤقت ويُسجل. (3) توضع كومة من ورق الجرائد على الأرضية تحت المؤقت لتصطدم بها الكتلة. (4) يُقطع نحو 70 cm من الشريط، ويُدخل طرفه في المؤقت، ويُربط طرفه الآخر بالكتلة بالشريط اللاصق. (5) تُمسك الكتلة عند حافة الطاولة بمحاذاة المؤقت. (6) يُشغل المؤقت وتُترك الكتلة تسقط سقوطًا حرًا. (7) يُفحص الشريط للتأكد من وضوح النقاط وعدم وجود فراغات. (8) تُختار نقطة «0» على بعد بضعة سنتمترات من بداية الشريط، وتُرقّم النقاط بعدها. (9) تُقاس المسافة من النقطة 0 إلى كل نقطة لأقرب ملمتر، ويُحسب الزمن المرتبط بكل نقطة من الزمن الدوري. ثم تُحسب $\frac{\boldsymbol{d}_f}{t_f}$ وتُمثل مقابل $t_f$، ويكون $g = 2 \times$ الميل. احتياط السلامة: الابتعاد عن الكتلة في أثناء سقوطها.', '["تثبيت المؤقت وتعيين زمنه الدوري","ربط الشريط بالكتلة وإسقاطها مع تشغيل المؤقت","اختيار النقطة 0 وقياس المسافات والأزمنة","التمثيل البياني وg = 2 × الميل","احتياط سلامة"]'::jsonb, '[]'::jsonb, '[{"element":"التجهيز","marks":1},{"element":"الإسقاط","marks":1},{"element":"القياس","marks":1},{"element":"التحليل","marks":1},{"element":"السلامة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة مرتبة مع التحليل والسلامة"},{"level":"3–4 درجات","description":"خطوات صحيحة ينقصها التحليل أو السلامة"},{"level":"1–2 درجة","description":"خطوات ناقصة غير مرتبة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["بدء القياس من أول نقطة على الشريط","إغفال تعيين الزمن الدوري","إطلاق الكتلة قبل تشغيل المؤقت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:58.915Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المقطع الرأسي: $\boldsymbol{v}_i = 0.30\ \text{m/s}$. (ب) الميل $= \frac{2.70 - 0.30}{0.50 - 0} = 4.80\ \text{m/s}^2 = \frac{1}{2}g$، فإن $g = 9.60\ \text{m/s}^2$. (ج) الخطأ النسبي $= \frac{9.80 - 9.60}{9.80} \times 100\% = 2.0\%$. (د) احتكاك الشريط بالمؤقت يعيق حركة الكتلة، ومقاومة الهواء للكتلة والشريط؛ فكلاهما يقلل التسارع المقيس. (ويُقبل أيضًا: أخطاء قياس المسافات أو عدم دقة الزمن الدوري.)', '["$\\boldsymbol{v}_i = 0.30\\ \\text{m/s}$","الميل 4.80 m/s²","g = 9.60 m/s²","الخطأ النسبي 2.0%","سببان معقولان (احتكاك الشريط، مقاومة الهواء)"]'::jsonb, '["المقطع $= 0.30\\ \\text{m/s}$","الميل $= \\frac{2.70 - 0.30}{0.50} = 4.80\\ \\text{m/s}^2$","$g = 2 \\times 4.80 = 9.60\\ \\text{m/s}^2$","الخطأ النسبي $= \\frac{0.20}{9.80} \\times 100\\% = 2.0\\%$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابات صحيحة للأجزاء الأربعة"},{"level":"3–4 درجات","description":"حساب g صحيح مع نقص في جزء آخر"},{"level":"1–2 درجة","description":"قراءة المقطع أو الميل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الميل 4.80 هو g","حساب الميل بقسمة 2.70 على 0.50 دون طرح المقطع","ذكر «خطأ في الحساب» سببًا عامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:58.915Z"}'::jsonb)
